static bool i_parseInt(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                       int nargs, union dvm_value *out)
{
   (void)self;
   const char *s = dvm_string_utf8(vm, ARG(0).l);
   int base = (nargs >= 2) ? ARG(1).i : 10;
   if (!s) { dvm__throw(vm, "java/lang/NumberFormatException", "null"); return false; }
   char *end = NULL;
   long v = strtol(s, &end, base);
   if (end == s) { dvm__throw(vm, "java/lang/NumberFormatException", "%s", s); return false; }
   RETI((int32_t)v);
}

static bool l_parseLong(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                        int nargs, union dvm_value *out);

/* Integer.valueOf(String[, radix]) / Long.valueOf(String[, radix]): parse and
 * then box.  These used to share the plain valueOf(int), which boxed the
 * *string reference* as if it were the number. */
static bool i_valueOf_str(struct dvm *vm, dvm_ref self,
                          const union dvm_value *args, int nargs,
                          union dvm_value *out)
{
   union dvm_value parsed = { 0 };
   if (!i_parseInt(vm, self, args, nargs, &parsed)) return false;
   RETL(box_make(vm, "Ljava/lang/Integer;", parsed));
}

static bool l_valueOf_str(struct dvm *vm, dvm_ref self,
                          const union dvm_value *args, int nargs,
                          union dvm_value *out)
{
   union dvm_value parsed = { 0 };
   if (!l_parseLong(vm, self, args, nargs, &parsed)) return false;
   RETL(box_make(vm, "Ljava/lang/Long;", parsed));
}

static bool i_decode(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                     int nargs, union dvm_value *out)
{
   (void)self; (void)nargs;
   const char *s = dvm_string_utf8(vm, ARG(0).l);
   if (!s) { dvm__throw(vm, "java/lang/NumberFormatException", "null"); return false; }
   char *end = NULL;
   long value = strtol(s, &end, 0);
   if (end == s || *end) {
      dvm__throw(vm, "java/lang/NumberFormatException", "%s", s);
      return false;
   }
   union dvm_value boxed = { .i = (int32_t)value };
   RETL(box_make(vm, "Ljava/lang/Integer;", boxed));
}

static bool l_parseLong(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                        int nargs, union dvm_value *out)
{
   (void)self;
   const char *s = dvm_string_utf8(vm, ARG(0).l);
   int base = (nargs >= 2) ? ARG(1).i : 10;
   if (!s) { dvm__throw(vm, "java/lang/NumberFormatException", "null"); return false; }
   char *end = NULL;
   long long v = strtoll(s, &end, base);
   if (end == s) { dvm__throw(vm, "java/lang/NumberFormatException", "%s", s); return false; }
   RETJ(v);
}

/* Java floating syntax differs from strtod: exact NaN/Infinity spelling,
 * no nan(payload), mandatory hex exponent, and an optional type suffix. */
static bool fp_parse_string(struct dvm *vm, dvm_ref ref, bool is_float,
                            union dvm_value *value)
{
   const char *text = ref ? dvm_string_utf8(vm, ref) : NULL;
   if (!text) {
      dvm__throw(vm, "java/lang/NullPointerException", "floating string"); return false;
   }
   size_t begin = 0, end = dvm_string_utf8_length(vm, ref);
   while (begin < end && (unsigned char)text[begin] <= 32) ++begin;
   while (end > begin && (unsigned char)text[end - 1] <= 32) --end;
   size_t p = begin;
   if (p < end && (text[p] == '+' || text[p] == '-')) ++p;
   if (end - p == 3 && !memcmp(text + p, "NaN", 3)) {
      if (is_float) value->f = NAN; else value->d = NAN;
      return true;
   }
   if (end - p == 8 && !memcmp(text + p, "Infinity", 8)) {
      double infinity = text[begin] == '-' ? -INFINITY : INFINITY;
      if (is_float) value->f = (float)infinity; else value->d = infinity;
      return true;
   }
   bool hex = end - p >= 2 && text[p] == '0' && (text[p + 1] == 'x' || text[p + 1] == 'X');
   if (hex) p += 2;
   size_t digits = 0;
   for (int fraction = 0; fraction < 2; ++fraction) {
      while (p < end && ((text[p] >= '0' && text[p] <= '9') ||
             (hex && ((text[p] >= 'a' && text[p] <= 'f') || (text[p] >= 'A' && text[p] <= 'F'))))) {
         ++p; ++digits;
      }
      if (fraction || p == end || text[p] != '.') break;
      ++p;
   }
   if (!digits) goto invalid;
   if (p < end && (hex ? (text[p] == 'p' || text[p] == 'P') : (text[p] == 'e' || text[p] == 'E'))) {
      ++p;
      if (p < end && (text[p] == '+' || text[p] == '-')) ++p;
      size_t exponent = p;
      while (p < end && text[p] >= '0' && text[p] <= '9') ++p;
      if (p == exponent) goto invalid;
   } else if (hex) goto invalid;
   size_t numeric_end = p;
   if (p < end && (text[p] == 'f' || text[p] == 'F' || text[p] == 'd' || text[p] == 'D')) ++p;
   if (p != end) goto invalid;
   char *number = luna_strndup(text + begin, numeric_end - begin);
   if (!number) { dvm__throw(vm, "java/lang/OutOfMemoryError", "floating string"); return false; }
   /* Host LC_NUMERIC remains C; guest locale changes are kept in guest state.
    * Convert directly to float to avoid double rounding. ERANGE is valid Java
    * overflow/underflow and preserves signed zero. */
   if (is_float) value->f = strtof(number, NULL);
   else value->d = strtod(number, NULL);
   free(number);
   return true;
invalid:
   dvm__throw(vm, "java/lang/NumberFormatException", "%s", text);
   return false;
}

static bool f_parseFloat(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                         int nargs, union dvm_value *out)
{
   (void)self; (void)nargs;
   return fp_parse_string(vm, ARG(0).l, true, out);
}

static bool d_parseDouble(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                          int nargs, union dvm_value *out)
{
   (void)self; (void)nargs;
   return fp_parse_string(vm, ARG(0).l, false, out);
}

static bool fp_valueOf_string(struct dvm *vm, dvm_ref self,
                              const union dvm_value *args, int nargs,
                              union dvm_value *out)
{
   (void)self; (void)nargs;
   struct dvm_class *cls = self ? dvm_object_class(vm, self) : NULL;
   bool is_float = cls ? !strcmp(cls->name, "java/lang/Float")
                       : strstr(builtin_sig(), "Ljava/lang/Float;") != NULL;
   union dvm_value parsed = { 0 };
   if (!fp_parse_string(vm, ARG(0).l, is_float, &parsed)) return false;
   const char *desc = is_float ? "Ljava/lang/Float;" : "Ljava/lang/Double;";
   if (self) {
      struct dvm_object *o = dvm__obj(vm, self);
      if (o && o->slots) o->slots[0] = box_normalize(desc, parsed);
      RETV();
   }
   RETL(box_make(vm, desc, parsed));
}

static bool i_toString(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                       int nargs, union dvm_value *out)
{
   char buf[32];
   if (nargs >= 1) snprintf(buf, sizeof buf, "%d", ARG(0).i);
   else snprintf(buf, sizeof buf, "%d", box_get(vm, self).i);
   RETL(dvm_new_string(vm, buf));
}

/* Float/Double/Boolean/Character/Short/Byte had no toString().
 *
 * Without it the lookup falls through to Object.toString() and every boxed
 * value prints as `java/lang/Float@2071` — which is what a real device would
 * never show and what silently corrupted, among other things, the metadata
 * Bundle this title sends to Facebook (`android.max_aspect=java/lang/Float@…`
 * instead of the number).  String.valueOf(Object) and `"" + box` both land
 * here, so the damage is wherever a number is turned into text.
 *
 * Java prints the shortest decimal that reads back as the same value, and
 * always with a fractional part or an exponent.  Widening the precision until
 * the text round-trips is that rule, stated directly. */
static bool f32_bits_eq(float a, float b)
{
   uint32_t x, y;
   memcpy(&x, &a, sizeof x);
   memcpy(&y, &b, sizeof y);
   return x == y;
}

static bool f64_bits_eq(double a, double b)
{
   uint64_t x, y;
   memcpy(&x, &a, sizeof x);
   memcpy(&y, &b, sizeof y);
   return x == y;
}

static bool f32_ieee_eq(float a, float b)
{
   uint32_t x, y;
   memcpy(&x, &a, sizeof x);
   memcpy(&y, &b, sizeof y);
   if (((x | y) & 0x7fffffffu) == 0u) return true; /* ±0 */
   if ((x & 0x7fffffffu) > 0x7f800000u || (y & 0x7fffffffu) > 0x7f800000u)
      return false; /* NaN */
   return x == y;
}

static void box_fp_str(char *buf, size_t sz, double v, bool is_float)
{
   if (isnan(v)) { snprintf(buf, sz, "NaN"); return; }
   if (isinf(v)) {
      snprintf(buf, sz, signbit(v) ? "-Infinity" : "Infinity");
      return;
   }
   const int maxp = is_float ? 9 : 17;
   for (int prec = 1; prec <= maxp; ++prec) {
      snprintf(buf, sz, "%.*g", prec, v);
      const double back = strtod(buf, NULL);
      if (is_float ? f32_bits_eq((float)back, (float)v) : f64_bits_eq(back, v))
         break;
   }
   /* "1" is an int in Java's eyes; a float always shows a decimal point. */
   if (!strpbrk(buf, ".eEnI")) {
      size_t n = strlen(buf);
      if (n + 2 < sz) { buf[n] = '.'; buf[n + 1] = '0'; buf[n + 2] = '\0'; }
   }
}

