static bool sys_arraycopy(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                          int nargs, union dvm_value *out)
{
   (void)self; (void)nargs; (void)out;
   struct dvm_object *src = dvm__obj(vm, ARG(0).l);
   struct dvm_object *dst = dvm__obj(vm, ARG(2).l);
   int32_t sp = ARG(1).i, dp = ARG(3).i, n = ARG(4).i;
   if (!src || !dst) {
      dvm__throw(vm, "java/lang/NullPointerException", "arraycopy");
      return false;
   }
   bool src_refs = src->elem_kind == 'L' || src->elem_kind == '[';
   bool dst_refs = dst->elem_kind == 'L' || dst->elem_kind == '[';
   if (src->kind != DVM_OBJ_ARRAY || dst->kind != DVM_OBJ_ARRAY ||
       src_refs != dst_refs || (!src_refs && src->elem_kind != dst->elem_kind)) {
      dvm__throw(vm, "java/lang/ArrayStoreException", "incompatible array types");
      return false;
   }
   if (n < 0 || sp < 0 || dp < 0 ||
       (uint64_t)(uint32_t)sp + (uint32_t)n > src->length ||
       (uint64_t)(uint32_t)dp + (uint32_t)n > dst->length) {
      dvm__throw(vm, "java/lang/ArrayIndexOutOfBoundsException",
                 "arraycopy src=%u dst=%u srcPos=%d dstPos=%d length=%d",
                 src->length, dst->length, sp, dp, n);
      return false;
   }
   if (!n) RETV();
   /* Same-type and widening copies need no per-element type check. Overlap
    * is possible only within one array, which takes this memmove path. */
   if (!src_refs || dvm__class_assignable(vm, src->cls, dst->cls)) {
      size_t width = (size_t)dvm__elem_width(src->elem_kind);
      memmove((uint8_t *)dst->data + (size_t)dp * width,
              (const uint8_t *)src->data + (size_t)sp * width, (size_t)n * width);
      RETV();
   }
   /* Narrowing reference copies must keep the successfully copied prefix
    * if a later element cannot be stored (System.arraycopy's contract). */
   struct dvm_class *component = dst->cls ? dst->cls->elem : NULL;
   dvm_ref *input = src->data, *output = dst->data;
   for (int32_t i = 0; i < n; ++i) {
      dvm_ref item = input[(uint32_t)sp + (uint32_t)i];
      if (item && !dvm__class_assignable(vm, dvm_object_class(vm,item), component)) {
         dvm__throw(vm, "java/lang/ArrayStoreException", "incompatible element at %d", sp+i);
         return false;
      }
      output[(uint32_t)dp + (uint32_t)i] = item;
   }
   RETV();
}

