/* Thread.sleep and Thread.start: the VM runs on whichever guest thread made
 * the JNI call, and Lunaria's scheduler is cooperative — actually sleeping
 * would stall the pump loop, and spawning a host thread would let bytecode
 * run concurrently with the interpreter's single frame stack.  Both become
 * no-ops; a Runnable handed to start() is run inline instead. */
/* Defers a Runnable's run() to the next return to the JNI boundary.  Running
 * it inline is wrong for both callers: a worker's run() typically waits on a
 * queue the caller has not filled yet — Volley's dispatchers are started
 * before the first request is added — and a Handler.post() is by definition
 * work for later.  Returns false when the queue is full. */
static bool class_extends_proxy(struct dvm_class *c);
static void msg_recycle_unchecked(struct dvm *, dvm_ref);
static dvm_ref looper_main(struct dvm *vm);

static bool pending_reserve(struct dvm *vm)
{
   if (vm->npending < vm->pending_cap) return true;
   if (vm->pending_cap > INT_MAX / 2) return false;
   const int cap = vm->pending_cap ? vm->pending_cap * 2 : 64;
#define GROW_PENDING(member) do { \
      void *p = realloc(vm->member, (size_t)cap * sizeof *vm->member); \
      if (!p) return false; \
      vm->member = p; \
   } while (0)
   GROW_PENDING(pending_threads);
   GROW_PENDING(pending_is_thread);
   GROW_PENDING(pending_due_ms);
   GROW_PENDING(pending_looper);
   GROW_PENDING(pending_owner);
   GROW_PENDING(pending_token);
#undef GROW_PENDING
   vm->pending_cap = cap;
   return true;
}

static bool queue_runnable_for(struct dvm *vm, dvm_ref r, bool as_thread,
                               int64_t delay_ms, dvm_ref looper,
                               dvm_ref owner, dvm_ref token)
{
   dvm_ref target_looper = as_thread ? 0 : looper ? looper : looper_main(vm);
   union dvm_value quitting = { 0 };
   if (target_looper && dvm_get_field(vm, target_looper, "quit", "Z", &quitting)
       && quitting.i) return false;
   struct dvm_class *c = r ? dvm_object_class(vm, r) : NULL;
   struct dvm_method *run = c ? dvm_find_method(vm, c, "run", "()V") : NULL;
   if ((!run && !class_extends_proxy(c)) ||
       (run && !run->has_code && !run->builtin))
      return true;   /* nothing to run: done */
   if (!pending_reserve(vm)) {
      /* Only actual allocation failure can reject a post. */
      static int warned;
      if (warned++ < 8)
         fprintf(stderr, "[sched] queue allocation failed (%d): %s.run()\n",
                 vm->npending, c && c->name ? c->name : "?");
      return false;
   }
   dvm_pin(vm, r);
   vm->pending_is_thread[vm->npending] = as_thread;
   vm->pending_due_ms[vm->npending] =
      delay_ms > 0 ? dvm__now_ms() + (uint64_t)delay_ms : 0;
   /* Thread.start has no Looper; Handler.post carries the one it was built
    * against.  Main-looper posts are stored as 0 so the existing main drain
    * keeps picking them without comparing against g_main_looper every time. */
   vm->pending_looper[vm->npending] = as_thread ? 0 : looper;
   /* Who posted it and under which token — Handler.removeCallbacksAndMessages
    * is defined in terms of exactly these two. */
   vm->pending_owner[vm->npending] = as_thread ? 0 : owner;
   vm->pending_token[vm->npending] = as_thread ? 0 : token;
   vm->pending_threads[vm->npending++] = r;
   if (target_looper) dvm_gil_notify_for(target_looper);
   if (vm->trace)
      fprintf(stderr, "[dvm] queue runnable=@%x thread=%d delay=%lld pending=%d\n",
              r, as_thread ? 1 : 0, (long long)delay_ms, vm->npending);
   else if (dvm__sched_trace_for(c ? c->name : NULL)) {
      fprintf(stderr, "[sched] queue %s thread=%d delay=%lld pending=%d looper=%u owner=%u\n",
              c && c->name ? c->name : "?", as_thread ? 1 : 0,
              (long long)delay_ms, vm->npending, looper, owner);
      for (int i = vm->ncallstack - 1, shown = 0;
           i >= 0 && shown < 6; --i, ++shown) {
         const struct dvm_method *f = vm->callstack[i];
         if (f) fprintf(stderr, "[sched]   from %s.%s%s\n",
                        f->cls ? f->cls->name : "?", f->name,
                        f->sig ? f->sig : "");
      }
   }
   return true;
}

static bool queue_runnable_at(struct dvm *vm, dvm_ref r, bool as_thread,
                              int64_t delay_ms, dvm_ref looper)
{
   return queue_runnable_for(vm, r, as_thread, delay_ms, looper, 0, 0);
}

static bool queue_runnable(struct dvm *vm, dvm_ref r, bool as_thread)
{
   return queue_runnable_at(vm, r, as_thread, 0, 0);
}

/* The drain in dvm.c puts a thread that parked back on the queue through
 * here; see dvm__requeue_parked()'s comment there for why. */
bool dvm__queue_runnable_at(struct dvm *vm, dvm_ref r, bool as_thread,
                            int64_t delay_ms)
{
   return queue_runnable_at(vm, r, as_thread, delay_ms, 0);
}

/* Bytecode threads, on host threads.
 *
 * The queue above is what a Thread.start() used to become: the Runnable was
 * held until the VM returned to the JNI boundary and then run to completion on
 * the one interpreting thread, under a step budget.  That is right for a
 * worker that services a queue and returns, and wrong for one that blocks —
 * bytecode frames live on the host C stack, so a thread inside a socket read
 * cannot be set aside, and while it sits there it holds the whole emulator.
 * The game's patcher copies 13.7 GB inside one doInBackground(): the engine
 * stopped rendering for the duration, and the budget that kept the freeze
 * bounded aborted the copy instead.
 *
 * A host thread per Thread gives each its own stack, so blocking becomes
 * something one thread does rather than something the VM does.  The
 * interpreter lock still admits one of them at a time — see dvm.h. */
struct bytecode_thread {
   struct dvm *vm;
   dvm_ref self;
   pthread_t thread;
   struct bytecode_thread *next;
   bool finished; /* under the interpreter lock */
};

/* Bytecode threads currently alive.  Only ever touched while the interpreter
 * lock is held, so a plain int is enough — and it is the answer to "could
 * anything other than the pending queue still produce a result?", which the
 * blocking primitives below have to ask before they give up waiting. */
static int g_live_bytecode_threads;

bool dvm__other_threads_live(void)
{
   return g_live_bytecode_threads > 0;
}

static void *bytecode_thread_main(void *p)
{
   struct bytecode_thread *a = p;
   struct dvm *vm = a->vm;
   dvm_ref self = a->self;

   dvm__mark_bytecode_thread();
   dvm_gil_acquire(vm);
   /* The process-wide order is DVM GIL outside, ARM execution lock inside.
    * Attaching publishes the Android thread identity under the latter. */
   arm_exec_dvm_thread_attach();
   dvm__tstate_reset(vm);
   vm->cur_thread = self;
   thread_base_set(vm,self,"hostThread","J",(union dvm_value){.ju=luna_os_thread_token()});
   thread_apply_priority(vm,self,thread_base_get(vm,self,"priority","I").i);
   vm->quiet_uncaught = true;

   for (;;) {
      if (dvm_is_stopping(vm)) break;
      struct dvm_class *c = dvm_object_class(vm, self);
      struct dvm_method *run = c ? dvm_find_method(vm, c, "run", "()V") : NULL;
      if (!run || (!run->has_code && !run->builtin)) break;
      union dvm_value ret;
      (void)dvm_call(vm, run, self, NULL, 0, &ret);
      /* A park is not an ending: the thread is blocked inside the platform on
       * something another thread has to produce, and the unwind that reports
       * it has already dropped the frames.  Re-enter run() the way the queue
       * re-ran it, on the same retry interval, until it finishes for real.
       * Anything else that unwound is an exception the thread's own catch did
       * not handle. quiet_uncaught keeps it from being printed at the call,
       * and clearing it here used to end a NetworkDispatcher with no trace at
       * all — the response had already been read and then was never posted. */
      const bool parked = vm->parked;
      if (!parked && vm->exception) {
         char buf[512];
         dvm_describe_exception(vm, vm->exception, buf, sizeof buf);
         struct dvm_class *tc = dvm_object_class(vm, self);
         fprintf(stderr, "[dvm] bytecode thread %s died: %s\n",
                 tc && tc->name ? tc->name : "?", buf);
         for (int i = 0; i < vm->nexc_trace; ++i) {
            struct dvm_method *f = vm->exc_trace[i];
            if (!f) continue;
            fprintf(stderr, "[dvm]   at %s.%s%s\n",
                    f->cls ? f->cls->name : "?", f->name,
                    f->sig ? f->sig : "");
         }
      }
      dvm_clear_exception(vm);
      if (!parked || dvm_is_stopping(vm)) break;
      dvm_gil_release(vm);
      usleep(DVM_PARK_RETRY_MS * 1000u);
      dvm_gil_acquire(vm);
   }

   dvm_gil_release(vm);
   arm_exec_dvm_thread_detach();
   dvm_gil_acquire(vm);
   union dvm_value dead = { .i = 0 };
   (void)dvm_set_field(vm, self, "alive", "Z", dead);
   dvm__thread_set_state(vm, self, DVM_THREAD_TERMINATED);
   --g_live_bytecode_threads;
   dvm_unpin(vm, self);
   a->finished = true;
   dvm_gil_release(vm);
   dvm_gil_notify_for(self); /* joiners for this thread only */
   return NULL;
}

/* Returns false when the thread could not be started, so the caller can fall
 * back to the queue rather than dropping the Runnable. */
static bool spawn_bytecode_thread(struct dvm *vm, dvm_ref self)
{
   if (dvm_is_stopping(vm)) return true;
   /* Java join uses the alive field, but process teardown also needs host
    * joins. Reap finished host threads here so short-lived threads do not
    * accumulate process-lifetime records. */
   struct bytecode_thread **link = &vm->host_threads;
   while (*link) {
      struct bytecode_thread *old = *link;
      if (!old->finished) { link = &old->next; continue; }
      *link = old->next;
      pthread_join(old->thread, NULL);
      free(old);
   }
   /* LUNARIA_DVM_THREADS=0 puts Thread.start() back on the pending queue.
    * Real threads change the order an app's callbacks arrive in, which is the
    * first thing to rule out when a title behaves differently from before. */
   static int enabled = -1;
   if (enabled < 0) {
      const char *e = getenv("LUNARIA_DVM_THREADS");
      enabled = (e && !strcmp(e, "0")) ? 0 : 1;
   }
   if (!enabled) return false;

   struct dvm_class *c = self ? dvm_object_class(vm, self) : NULL;
   struct dvm_method *run = c ? dvm_find_method(vm, c, "run", "()V") : NULL;
   if (!run || (!run->has_code && !run->builtin)) {
      (void)dvm_set_field(vm, self, "alive", "Z", (union dvm_value){.i = 0});
      dvm__thread_set_state(vm, self, DVM_THREAD_TERMINATED);
      return true;
   }

   struct bytecode_thread *a = calloc(1, sizeof *a);
   if (!a) return false;
   a->vm = vm;
   a->self = self;

   /* Pinned before the thread exists, because the moment it does it is a root
    * this VM has no other record of. */
   dvm_pin(vm, self);
   union dvm_value live = { .i = 1 };
   (void)dvm_set_field(vm, self, "alive", "Z", live);

   pthread_attr_t attr;
   pthread_attr_init(&attr);
   /* Joinable for process teardown; Java Thread.join() still waits on alive. */
   /* Interpreted frames and sanitizer redzones need more host space than
    * compiled ART frames. Invocation checks the actual stack boundary and
    * reserves space for StackOverflowError construction and unwinding. */
   pthread_attr_setstacksize(&attr, 4u << 20);

   ++g_live_bytecode_threads;
   int rc = pthread_create(&a->thread, &attr, bytecode_thread_main, a);
   pthread_attr_destroy(&attr);
   if (rc != 0) {
      static int warned;
      if (warned++ < 8)
         fprintf(stderr, "[dvm] could not start a host thread for %s.run(): %s"
                 " — falling back to the queue\n",
                 run->cls ? run->cls->name : "?", strerror(rc));
      union dvm_value dead = { .i = 0 };
      (void)dvm_set_field(vm, self, "alive", "Z", dead);
      --g_live_bytecode_threads;
      dvm_unpin(vm, self);
      free(a);
      return false;
   }
   a->next = vm->host_threads;
   vm->host_threads = a;
   /* Capped, and unconditional: which of an app's threads became real ones is
    * the first thing to check when the VM behaves differently from before. */
   static int started;
   if (started++ < 24 || dvm__sched_trace_for(run->cls ? run->cls->name : NULL))
      fprintf(stderr, "[dvm-thread] host thread #%d for %s.run()\n",
              started, run->cls ? run->cls->name : "?");
   return true;
}

void dvm_threads_finish(struct dvm *vm)
{
   if (!vm) return;
   dvm_request_stop(vm);
   dvm_gil_acquire(vm);
   struct bytecode_thread *threads = vm->host_threads;
   vm->host_threads = NULL;
   unsigned gil = dvm_gil_unlock_all(vm);
   unsigned arm = arm_lock_unlock_all();
   while (threads) {
      struct bytecode_thread *next = threads->next;
      pthread_join(threads->thread, NULL);
      free(threads);
      threads = next;
   }
   dvm_gil_relock(vm, gil);
   arm_lock_relock(arm);
   dvm_gil_release(vm);
}

static bool t_start(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                    int nargs, union dvm_value *out)
{
   (void)args; (void)nargs; (void)out;
   union dvm_value started={0};
   (void)dvm__get_field_from(vm,self,dvm_find_class(vm,"java/lang/Thread"),"started","Z",&started);
   if (started.i) {
      dvm__throw(vm,"java/lang/IllegalThreadStateException","Thread already started");
      return false;
   }
   dvm__thread_set_state(vm, self, DVM_THREAD_RUNNABLE);
   if (spawn_bytecode_thread(vm, self)) RETV();
   /* pthread creation failure leaves the cooperative execution path. */
   if (queue_runnable(vm, self, true)) RETV();

   struct dvm_class *c = dvm_object_class(vm, self);
   struct dvm_method *run = c ? dvm_find_method(vm, c, "run", "()V") : NULL;
   union dvm_value ret;
   if (run) (void)dvm_call(vm, run, self, NULL, 0, &ret);
   (void)dvm_set_field(vm, self, "alive", "Z", (union dvm_value){.i = 0});
   dvm__thread_set_state(vm, self, DVM_THREAD_TERMINATED);
   RETV();
}

