/* Thread.isAlive().
 *
 * A thread started from bytecode lives in the pending-runnable queue until its
 * run() has returned, so "queued or running" is exactly "alive".  The download
 * hands the MD5 check to its own Thread and then polls this in a loop, so a
 * missing isAlive() left it with no way to learn the check had finished — and
 * the file was reported as a checksum mismatch.  Like join(), this yields
 * first: in a cooperative VM the thread being asked about cannot make any
 * progress while its caller spins. */
static bool t_isDaemon(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                       int nargs, union dvm_value *out)
{
   (void)args; (void)nargs;
   union dvm_value d = { 0 };
   (void)dvm_get_field(vm, self, "daemon", "Z", &d);
   RETI(d.i);
}

static bool t_isAlive(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                      int nargs, union dvm_value *out)
{
   (void)args; (void)nargs;
   if (dvm__current_thread(vm) == self) RETI(1);   /* asking about itself */
   union dvm_value native = { 0 };
   (void)dvm_get_field(vm, self, "nativeToken", "J", &native);
   if (native.j && arm_exec_jni_thread_alive)
      RETI(arm_exec_jni_thread_alive((uint64_t)native.j));
   /* A thread that got a host thread says so itself. */
   union dvm_value alive = { 0 };
   if (dvm_get_field(vm, self, "alive", "Z", &alive) && alive.i) RETI(1);
   /* Otherwise it is one the queue took: still pending means still to run,
    * and the drain gives it the chance to, so that the answer describes what
    * happened rather than what had not been got round to yet. */
   bool queued = false;
   for (int i = 0; i < vm->npending; ++i)
      if (vm->pending_threads[i] == self) { queued = true; break; }
   if (!queued) RETI(0);
   dvm__drain_for_wait(vm);
   queued = false;
   for (int i = 0; i < vm->npending; ++i)
      if (vm->pending_threads[i] == self) { queued = true; break; }
   RETI(queued ? 1 : 0);
}

static bool t_getState(struct dvm *vm, dvm_ref self,
                        const union dvm_value *args, int nargs,
                        union dvm_value *out)
{
   (void)args; (void)nargs;
   static const char *const names[] = {
      "NEW", "RUNNABLE", "BLOCKED", "WAITING", "TIMED_WAITING", "TERMINATED"
   };
   union dvm_value state = {0}, native = {0}, result = {0};
   (void)dvm_get_field(vm, self, "javaState", "I", &state);
   (void)dvm_get_field(vm, self, "nativeToken", "J", &native);
   if (native.j && arm_exec_jni_thread_alive &&
       !arm_exec_jni_thread_alive((uint64_t)native.j))
      state.i = DVM_THREAD_TERMINATED;
   struct dvm_class *cls = dvm__class_by_desc(vm, "Ljava/lang/Thread$State;");
   if (state.i < DVM_THREAD_NEW || state.i > DVM_THREAD_TERMINATED) return false;
   (void)dvm_get_static(vm, cls, names[state.i], "Ljava/lang/Thread$State;", &result);
   RETL(result.l);
}

static bool t_join(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                   int nargs, union dvm_value *out)
{
   /* join(millis); 0 or absent means wait for as long as it takes. */
   int64_t limit_ms = (nargs > 0) ? ARG(0).j : 0;
   if (dvm__thread_take_interrupt(vm)) {
      dvm__throw(vm, "java/lang/InterruptedException", "join interrupted");
      return false;
   }
   uint64_t deadline = limit_ms > 0 ? dvm__now_ms() + (uint64_t)limit_ms : 0;

   for (;;) {
      if (dvm_is_stopping(vm)) return false;
      union dvm_value alive = { 0 };
      if (!dvm_get_field(vm, self, "alive", "Z", &alive) || !alive.i) break;
      if (deadline && dvm__now_ms() >= deadline) break;
      /* The thread being joined runs under the same lock, so waiting for it
       * means giving the lock up — holding it here is the one thing that
       * guarantees it never finishes. */
      if (!dvm_gil_held(vm)) break; /* not ours to give up: nothing can change */
      uint64_t now = dvm__now_ms();
      uint64_t left = !deadline ? DVM_BLOCK_MAX_MS
                    : deadline > now ? deadline - now : 1;
      dvm_ref current = dvm__current_thread(vm);
      dvm__thread_set_state(vm, current, deadline ? DVM_THREAD_TIMED_WAITING : DVM_THREAD_WAITING);
      dvm__thread_set_wait(vm, (uintptr_t)self);
      dvm_gil_wait_for(vm, self, (unsigned)left);
      dvm__thread_set_wait(vm, 0);
      dvm__thread_set_state(vm, current, DVM_THREAD_RUNNABLE);
      if (dvm__thread_take_interrupt(vm)) {
         dvm__throw(vm, "java/lang/InterruptedException", "join interrupted");
         return false;
      }
   }
   /* A thread the queue took instead still needs the drain to make progress. */
   dvm__drain_for_wait(vm);
   RETV();
}

