   union dvm_value key = { .l = self }, present = { 0 }, value = { 0 };
   if (!map_containsKey(vm, values, &key, 1, &present)) return false;
   if (present.i) return map_get(vm, values, &key, 1, out);
   struct dvm_class *c = dvm_object_class(vm, self);
