/* Event source belongs to EventObject even when a subclass hides it. */
static bool event_object_call(struct dvm *vm, dvm_ref self,
                              const union dvm_value *args, int nargs,
                              union dvm_value *out)
{
   (void)nargs;
   struct dvm_class *base = dvm_find_class(vm, "java/util/EventObject");
   const char *name = dvm__builtin_method()->name;
   union dvm_value source = {0};
   if (!strcmp(name, "<init>")) {
      if (!ARG(0).l) {
         dvm__throw(vm, "java/lang/IllegalArgumentException", "null source");
         return false;
      }
      return dvm__set_field_from(vm, self, base, "source", "Ljava/lang/Object;", ARG(0));
   }
   if (!dvm__get_field_from(vm, self, base, "source", "Ljava/lang/Object;", &source)) return false;
   if (!strcmp(name, "getSource")) RETL(source.l);
   union dvm_value text = {0};
   if (source.l) {
      struct dvm_method *method = dvm_find_method(vm, dvm_object_class(vm, source.l), "toString", "()Ljava/lang/String;");
      if (!method || !dvm_call(vm, method, source.l, NULL, 0, &text)) return false;
   }
   const char *value = text.l ? dvm_string_utf8(vm, text.l) : "null";
   const char *cls = dvm_object_class(vm, self)->name;
   size_t len = strlen(cls) + strlen(value ? value : "null") + 10;
   char *buf = malloc(len);
   if (!buf) { dvm__throw(vm, "java/lang/OutOfMemoryError", "EventObject.toString"); return false; }
   strcpy(buf, cls);
   for (char *c = buf; *c; ++c) if (*c == '/') *c = '.';
   strcat(buf, "[source="); strcat(buf, value ? value : "null"); strcat(buf, "]");
   dvm_ref result = dvm_new_string(vm, buf); free(buf); RETL(result);
}
