   static bool name(struct dvm *vm, dvm_ref self,                             \
                    const union dvm_value *args, int nargs,                   \
                    union dvm_value *out)                                     \
   { return afu_add(vm, self, ARG(0).l, (delta), (wide), (old), out); }
