   (void)dvm_get_field(vm, self, "screenLayout", "I", &layout);
   layout.i = (layout.i & ~CFG_LAYOUTDIR_MASK) |
              ((locale_is_rtl(vm, ARG(0).l) ? 2 : 1) << CFG_LAYOUTDIR_SHIFT);
   (void)dvm_set_field(vm, self, "screenLayout", "I", layout);
   (void)out;
