static bool bigint_bit_length(struct dvm *vm,dvm_ref self,const union dvm_value *args,int nargs,union dvm_value *out)
{
   (void)args; (void)nargs;
   BIGNUM *number=bigint_bn(vm,self);
   if (!number) return false;
   /* Java counts the minimum two's-complement bits, excluding the sign bit. */
   if (BN_is_negative(number)) {
      BN_set_negative(number,0);
      if (!BN_sub_word(number,1)) { BN_free(number); dvm__throw(vm,"java/lang/OutOfMemoryError","BigInteger bitLength"); return false; }
   }
   int length=BN_num_bits(number); BN_free(number); RETI(length);
}
