   char *quoted_path = juri_quote(path, ";/:@&=+$,");
   char *quoted_query = query ? juri_quote(query, ";/?:@&=+$,[]") : NULL;
   char *quoted_fragment = fragment ? juri_quote(fragment, ";/?:@&=+$,[]") : NULL;
