static bool conn_getOutputStream(struct dvm *vm, dvm_ref self,
                                 const union dvm_value *args, int nargs,
                                 union dvm_value *out)
{
   (void)args; (void)nargs;
   struct rt_conn *c = conn_of(vm, self);
   if (!c) RETL(0);
   /* The platform's own rule.  A caller that writes a body without asking for
    * one has a bug, and this exception is where it finds out; answering with
    * a stream instead sends a request nobody meant to send. */
   if (!c->do_output) {
      dvm__throw(vm, "java/net/ProtocolException",
                 "cannot write to a URLConnection if doOutput=false - "
                 "call setDoOutput(true)");
      return false;
   }
   if (!c->out_stream) {
      struct dvm_class *cls =
         dvm__class_by_desc(vm, "Ljava/io/ByteArrayOutputStream;");
      c->out_stream = cls ? dvm_new_object(vm, cls) : 0;
      if (c->out_stream) {
         union dvm_value ignored = { 0 };
         (void)st_init(vm, c->out_stream, NULL, 0, &ignored);
         /* The connection is the only reference until the caller stores it. */
         dvm_pin(vm, c->out_stream);
      }
   }
   RETL(c->out_stream);
}

/* Runs the exchange, once.  Every accessor that needs a reply funnels through
 * here, which is what connect()/getResponseCode()/getInputStream() all do on a
 * real HttpURLConnection. */
static bool conn_perform(struct dvm *vm, dvm_ref self, struct rt_conn *c)
{
   if (!c || c->performed) return c && !c->failed;
   c->connected = true;
   c->performed = true;

   const uint8_t *body = NULL;
   size_t body_len = 0;
   if (c->out_stream) {
      uint32_t n = 0;
      const uint8_t *p = stream_content(vm, c->out_stream, &n);
      if (p && n) {
         body = p;
         body_len = n;
      }
   }
   /* HttpURLConnection turns a doOutput connection whose method is still the
    * default GET into a POST — a GET with a body is not what the caller
    * asked for and not what a server will accept. */
   if (c->do_output && c->method && !strcmp(c->method, "GET")) {
      free(c->method);
      c->method = strdup("POST");
   }
   /* The jar, if the app installed one.  CookieHandler's contract is that the
    * *connection* consults it, not the caller: an app that calls
    * CookieHandler.setDefault() and nothing else still expects its session
    * cookie to come back on the next request. */
   if (net_cookies_enabled(vm)) {
      char jar_hdr[4096];
      if (cookie_jar_header(&g_net_jar, c->url, jar_hdr, sizeof jar_hdr))
         conn_set_header(c, "Cookie", jar_hdr, true);
   }
   /* Android prepares form media type for body-capable methods unless the
    * caller supplied one. Keep defaults on the wire, outside the caller's
    * request-property map, as HttpURLConnectionImpl.newHttpEngine does. */
   const bool permits_body = conn_permits_body(c->method);
   if (permits_body && !body) body = (const uint8_t *)"";
   bool have_type = false;
   for (int i = 0; i < c->nhdrs; ++i)
      if (c->hdrs[i].name && !strcasecmp(c->hdrs[i].name, "Content-Type")) have_type = true;
   struct dvm_http_header *wire_headers = c->hdrs;
   int wire_count = c->nhdrs;
   if (permits_body && !have_type) {
      wire_headers = malloc(((size_t)wire_count + 1) * sizeof *wire_headers);
      if (!wire_headers) {
         c->failed = true;
         dvm__throw(vm, "java/lang/OutOfMemoryError", "HTTP request headers");
         return false;
      }
      if (wire_count) memcpy(wire_headers, c->hdrs, (size_t)wire_count * sizeof *wire_headers);
      wire_headers[wire_count++] = (struct dvm_http_header){
         .name = "Content-Type", .value = "application/x-www-form-urlencoded"};
   }
   int timeout = c->connect_timeout > c->read_timeout ? c->connect_timeout
                                                      : c->read_timeout;
   bool verbose = getenv("LUNARIA_HTTP_TRACE") != NULL;
   if (verbose) {
      fprintf(stderr, "[http] > %s %s\n", c->method, c->url);
      for (int i = 0; i < wire_count; ++i)
         fprintf(stderr, "[http] > %s: %s\n", wire_headers[i].name,
                 wire_headers[i].value);
      if (body_len)
         fprintf(stderr, "[http] > body %zu: %.*s\n", body_len,
                 (int)(body_len > 512 ? 512 : body_len), (const char *)body);
   }
   /* The exchange blocks — connect, send, and wait for the reply headers —
    * and it was doing so with the interpreter lock held.  This title posts a
    * log line to Netmarble every few frames and each round trip took 130-180
    * ms, so the whole VM stopped for that long, and with it every UE thread
    * that wanted to make a JNI call: the lock read 99% held with a worst
    * single hold of 581 ms, and the title screen ran at 2 pump frames a
    * second.  Nothing here needs any of the VM, so give both locks back for
    * the duration, exactly as Thread.sleep() and the body read below do.
    *
    * What stays valid across the gap: `c` is the connection's own C
    * allocation, reachable from `self`, which is a live frame local; `body`
    * points into the pinned output stream's byte array, and objects here do
    * not move.  `c->performed` was set above, so a second perform on the same
    * connection returns early rather than issuing the request twice.  Nothing
    * else about the VM may be touched until the locks are back. */
   unsigned armd = arm_lock_unlock_all();
   unsigned gild = dvm_gil_unlock_all(vm);
   const bool ok = dvm_http_perform_connected(&c->transport, c->method, c->url, wire_headers, wire_count,
                                    body, body_len, timeout, c->follow,
                                    &c->resp);
   /* A reply framed by chunking or by the close of the connection has to be
    * read to its end before the length is known, which blocks for as long as
    * the exchange did — so it belongs inside the same gap. */
   if (ok && c->resp.content_length < 0) (void)dvm_http_slurp(&c->resp);
   dvm_gil_relock(vm, gild);
   arm_lock_relock(armd);
   if (wire_headers != c->hdrs) free(wire_headers);
   if (!ok) {
      c->failed = true;
      fprintf(stderr, "[http] %s %s failed: %s\n", c->method, c->url,
              c->resp.error);
      dvm__throw(vm, "java/io/IOException", "%s", c->resp.error);
      return false;
   }
   if (net_cookies_enabled(vm))
      for (int i = 0; i < c->resp.nheaders; ++i)
         if (!strcasecmp(c->resp.headers[i].name, "Set-Cookie") ||
             !strcasecmp(c->resp.headers[i].name, "Set-Cookie2"))
            cookie_jar_set(&g_net_jar, c->url, c->resp.headers[i].value);
   /* Streaming only pays when the length is known up front, and that is
    * exactly the case that needs it: the content paks are gigabytes each and
    * always carry Content-Length. */
   if (c->resp.body)
      fprintf(stderr, "[http] %s %s -> %d (%zu bytes)\n", c->method, c->url,
              c->resp.status, c->resp.body_len);
   else
      fprintf(stderr, "[http] %s %s -> %d (%lld bytes streaming)\n", c->method,
              c->url, c->resp.status, c->resp.content_length);
   /* An error status is where a wrong request shows itself, and the body says
    * why; it is too useful to need a rebuild to see.  Reading it is safe: an
    * error body is a sentence, not a download. */
   if (verbose || c->resp.status >= 400) {
      /* And the request that produced it.  "NP not found" says nothing on its
       * own; which identity was asked for is the whole question, and a
       * request the emulator assembled wrongly is invisible otherwise. */
      if (body && body_len)
         fprintf(stderr, "[http] > body: %.*s\n",
                 (int)(body_len > 512 ? 512 : body_len), (const char *)body);
      for (int i = 0; verbose && i < c->resp.nheaders; ++i)
         fprintf(stderr, "[http] < %s: %s\n", c->resp.headers[i].name,
                 c->resp.headers[i].value);
      if (dvm_http_slurp(&c->resp) && c->resp.body_len)
         fprintf(stderr, "[http] < body: %.*s\n",
                 (int)(c->resp.body_len > 512 ? 512 : c->resp.body_len),
                 (const char *)c->resp.body);
   }
   (void)self;
   return true;
}

static bool conn_connect(struct dvm *vm, dvm_ref self,
                         const union dvm_value *args, int nargs,
                         union dvm_value *out)
{
   (void)args; (void)nargs; (void)out;
   struct rt_conn *c = conn_of(vm, self);
   if (!c) RETV();
   if (c->connected || c->performed) RETV();
   /* connect establishes transport. Sending here loses a body written to
    * getOutputStream after an explicit connect, which Android permits. */
   unsigned arm_depth = arm_lock_unlock_all();
   unsigned gil_depth = dvm_gil_unlock_all(vm);
   c->transport = dvm_http_connect(c->url, c->connect_timeout,
                                  c->resp.error, sizeof c->resp.error);
   dvm_gil_relock(vm, gil_depth);
   arm_lock_relock(arm_depth);
   if (!c->transport) {
      dvm__throw(vm, "java/io/IOException", "%s", c->resp.error);
      return false;
   }
   c->connected = true;
   RETV();
}

