/* Builds an array-backed stream over the whole body.  Only getErrorStream()
 * uses it now — an error body is small by nature, so reading it whole is
 * fine, which is exactly what is not true of the response to a GET. */
static bool conn_body_stream(struct dvm *vm, struct rt_conn *c,
                             union dvm_value *out)
{
   if (!dvm_http_slurp(&c->resp)) RETL(0);
   struct dvm_class *cls =
      dvm__class_by_desc(vm, "Ljava/io/ByteArrayInputStream;");
   dvm_ref s = cls ? dvm_new_object(vm, cls) : 0;
   if (!s) RETL(0);
   uint32_t n = (uint32_t)c->resp.body_len;
   dvm_ref a = dvm_new_array(vm, 'B', "B", n);
   struct dvm_object *ao = a ? dvm__obj(vm, a) : NULL;
   if (ao && ao->data && n) memcpy(ao->data, c->resp.body, n);
   union dvm_value args[1] = { { .l = a } }, ignored = { 0 };
   (void)st_init_bytes(vm, s, args, 1, &ignored);
   RETL(s);
}

/* java.net.HttpURLConnection's own body stream.
 *
 * It reads from the still-open connection as the caller consumes it, which is
 * what the real class does and what this app needs: the downloader pulls a
 * multi-gigabyte pak through here a buffer at a time and writes it to disk.
 * Handing back an array of the whole body instead used to stop the emulator
 * outright at the first content file. */
static bool http_body_read(struct dvm *vm, dvm_ref self,
                           const union dvm_value *args, int nargs,
                           union dvm_value *out)
{
   union dvm_value cv = { 0 };
   (void)dvm_get_field(vm, self, "conn", "Ljava/net/HttpURLConnection;", &cv);
   struct rt_conn *c = cv.l ? conn_of(vm, cv.l) : NULL;
   if (!c) { dvm__throw(vm, "java/io/IOException", "stream closed"); return false; }

   uint8_t one;
   uint8_t *dst = &one;
   size_t count = 1;
   struct dvm_object *array = NULL;
   if (nargs) {
      array = dvm__obj(vm, ARG(0).l);
      int32_t offset = nargs >= 3 ? ARG(1).i : 0;
      int32_t want = nargs >= 3 ? ARG(2).i
                                : (array ? (int32_t)array->length : 0);
      if (!array || array->kind != DVM_OBJ_ARRAY || !array->data ||
          offset < 0 || want < 0 ||
          (uint32_t)(offset + want) > array->length) {
         dvm__throw(vm, "java/lang/IndexOutOfBoundsException", "read bounds");
         return false;
      }
      if (!want) RETI(0);
      dst = (uint8_t *)array->data + offset;
      count = (size_t)want;
   }
   /* Reading a body is the one place the emulator sits on a socket for
    * minutes at a time — a content pak is gigabytes.  That used to stop the
    * whole emulator, so this pumped the window's events from inside the read
    * to keep the desktop from marking it unresponsive.
    *
    * It is not needed now and must not stay: the read gives the interpreter
    * lock back below, so the frame pump keeps running on its own thread and
    * services the window itself.  Pumping events from here also meant
    * re-entering the host's event handling from an arbitrary depth of guest
    * bytecode, which is exactly the kind of re-entry the lock exists to
    * prevent. */
   /* The lock goes back for the duration.  `dst` points into an array object's
    * own allocation and `c` into the connection's, neither of which moves, so
    * they stay valid across the wait — but nothing else about the VM may be
    * touched until it is taken again. */
   /* Only give the lock up when the read would actually wait.  Read-ahead
    * means most of a download's reads are served from memory, and dropping
    * the lock for those puts this thread back at the end of a queue whose
    * head — the frame pump — holds it for a whole frame. */
   long n;
   if (dvm_http_avail(&c->resp) >= count) {
      n = dvm_http_read(&c->resp, dst, count);
   } else {
      unsigned gil = dvm_gil_unlock_all(vm);
      n = dvm_http_read(&c->resp, dst, count);
      dvm_gil_relock(vm, gil);
   }
   if (n < 0) {
      dvm__throw(vm, "java/io/IOException", "%s", c->resp.error);
      return false;
   }
   if (!n) RETI(-1);            /* end of body */
   dvm__note_io_progress(vm, (size_t)n);
   RETI(nargs ? (int32_t)n : (int32_t)one);
}

static bool http_body_available(struct dvm *vm, dvm_ref self,
                                const union dvm_value *args, int nargs,
                                union dvm_value *out)
{
   (void)args; (void)nargs;
   union dvm_value cv = { 0 };
   (void)dvm_get_field(vm, self, "conn", "Ljava/net/HttpURLConnection;", &cv);
   struct rt_conn *c = cv.l ? conn_of(vm, cv.l) : NULL;
   if (!c) RETI(0);
   /* Close-terminated and chunked bodies are already in `resp.body`. Their
    * Content-Length is negative, so a remainder computed from that header is
    * always zero — and a caller that waits for available() to become positive
    * before it reads never does. The bytes already taken off the socket are
    * the amount that can be read without blocking. */
   size_t n = dvm_http_avail(&c->resp);
   if (n > 0x7fffffffu) n = 0x7fffffffu;
   RETI((int32_t)n);
}

static bool http_body_close(struct dvm *vm, dvm_ref self,
                            const union dvm_value *args, int nargs,
                            union dvm_value *out)
{
   (void)args; (void)nargs;
   union dvm_value cv = { 0 };
   (void)dvm_get_field(vm, self, "conn", "Ljava/net/HttpURLConnection;", &cv);
   struct rt_conn *c = cv.l ? conn_of(vm, cv.l) : NULL;
   /* Dropping the response drops the socket with it, which is what closing a
    * body stream means; the headers stay readable. */
   if (c) {
      const int status = c->resp.status;
      dvm_http_response_free(&c->resp);
      c->resp.status = status;
   }
   RETV();
}

