   int token = jr_token(vm, self);
   if (token < 0) return false;
   struct dvm_class *c = dvm__class_by_desc(vm, "Landroid/util/JsonToken;");
   RETL(c && c->sslots && token < c->nsslots ? c->sslots[token].l : 0);
