static bool prefs_publish_editor(struct dvm *vm, dvm_ref self, dvm_ref *notification)
{
   *notification=0;
   dvm_ref m=prefs_backing(vm,self), instance=0;
   for (int i=0;i<g_nprefs;++i) if(g_prefs[i].map==m) instance=g_prefs[i].instance;
   union dvm_value pending={0},clear={0},registry={0},ignored={0};
   (void)dvm_get_field(vm,self,"pending","Ljava/lang/Object;",&pending);
   (void)dvm_get_field(vm,self,"clear","Z",&clear);
   (void)dvm_get_field(vm,instance,"listeners","Ljava/util/Map;",&registry);
   struct dvm_object *o=dvm__obj(vm,pending.l), *r=dvm__obj(vm,registry.l);
   struct rt_map *changes=o ? o->data : NULL, *listeners=r ? r->data : NULL;
   uint32_t nchanges=changes ? changes->size : 0, nlisteners=listeners ? listeners->size : 0;
   if(!nchanges && !clear.i) return true;
   dvm_ref keys=0, snapshot=0;
   if(nlisteners) {
      keys=dvm_new_array(vm,'L',"Ljava/lang/String;",nchanges);
      snapshot=dvm_new_array(vm,'L',"Ljava/lang/Object;",nlisteners);
      *notification=dvm_new_object(vm,dvm_find_class(vm,"lunaria/PreferenceNotification"));
      if(!keys || !snapshot || !*notification) return false;
      dvm_ref *items=dvm_array_data(vm,snapshot);
      for(uint32_t i=0;i<nlisteners;++i) items[i]=listeners->e[i].k;
   }
   /* Publication is under the interpreter lock. Reset staging before
    * notifying Java, so callbacks can reuse this Editor without lost edits. */
   bool changed=false;
   if(clear.i) {
      struct dvm_object *backing=dvm__obj(vm,m);
      struct rt_map *map=backing ? backing->data : NULL;
      changed=map && map->size;
      if(!map_clear(vm,m,NULL,0,&ignored)) return false;
   }
   int count=0;
   for(uint32_t i=0;i<nchanges;++i) {
      o=dvm__obj(vm,pending.l); changes=o->data;
      union dvm_value pair[]={{.l=changes->e[i].k},{.l=changes->e[i].v}},old={0};
      if(!map_get(vm,m,pair,1,&old)) return false;
      if(!pair[1].l && !old.l) continue;
      if(pair[1].l && old.l && key_eq(vm,old.l,pair[1].l)) continue;
      if(dvm_exception(vm)) return false;
      if(pair[1].l) { if(!map_put(vm,m,pair,2,&ignored)) return false; }
      else if(!map_remove(vm,m,pair,1,&ignored)) return false;
      changed=true;
      if(keys) ((dvm_ref *)dvm_array_data(vm,keys))[count++]=pair[0].l;
   }
   if(!map_clear(vm,pending.l,NULL,0,&ignored)) return false;
   union dvm_value zero={0};
   if(!dvm_set_field(vm,self,"clear","Z",zero)) return false;
   if(changed) for(int i=0;i<g_nprefs;++i) if(g_prefs[i].map==m) ++g_prefs[i].generation;
   if(*notification) {
      union dvm_value value={.l=instance};
      (void)dvm_set_field(vm,*notification,"prefs","Landroid/content/SharedPreferences;",value);
      value.l=snapshot; (void)dvm_set_field(vm,*notification,"listeners","[Ljava/lang/Object;",value);
      value.l=keys; (void)dvm_set_field(vm,*notification,"keys","[Ljava/lang/String;",value);
      value.i=count; (void)dvm_set_field(vm,*notification,"count","I",value);
      value.i=clear.i && lunaria_app_target_sdk()>=30 && lunaria_sdk_int()>=30;
      (void)dvm_set_field(vm,*notification,"cleared","Z",value);
      if(!count && !value.i) *notification=0;
   }
   return true;
}

/* apply() and commit() are where a device makes the change durable.  They were
 * no-ops here because the map was already written; now they are also the point
 * the file is rewritten. */
static bool ed_flush(struct dvm *vm, dvm_ref self)
{
   dvm_ref m = prefs_backing(vm, self);
   const char *name = m ? prefs_name_of(m) : NULL;
   if (!name) return false;
   uint64_t generation = 0;
   for (int i = 0; i < g_nprefs; ++i)
      if (g_prefs[i].map == m) generation = g_prefs[i].generation;
   const bool saved = prefs_save(vm, name, m, false);
   for (int i = 0; i < g_nprefs; ++i)
      if (g_prefs[i].map == m && g_prefs[i].generation == generation)
         g_prefs[i].dirty = !saved;
   bool any = false;
   for (int i = 0; i < g_nprefs && !any; ++i) any = g_prefs[i].dirty;
   if (any) atomic_store_explicit(&g_prefs_any_dirty, true, memory_order_release);
   return saved;
}

/* The whole difference between apply() and commit() is who waits for the disk.
 * commit() writes the file and reports whether it worked; apply() changes the
 * in-memory preferences at once and leaves the write to the framework, which
 * coalesces it and completes it before the process can be torn down.
 *
 * Writing the file here as well made every apply() serialise the entire map
 * back to XML and rename it into place.  AppsFlyer's counters, which are
 * applied several times per SDK call, spent a Cross Worlds loading screen
 * inside luna_file_rename(2).  Now the map is marked and the frame pump writes it —
 * at most one write per file per frame, however many applies there were. */
static bool ed_apply(struct dvm *vm, dvm_ref self,
                     const union dvm_value *args, int nargs,
                     union dvm_value *out)
{
   (void)args; (void)nargs;
   dvm_ref notification=0;
   if(!prefs_publish_editor(vm,self,&notification)) return false;
   dvm_ref m = prefs_backing(vm, self);
   for (int i = 0; i < g_nprefs; ++i)
      if (g_prefs[i].map == m) {
         g_prefs[i].dirty = true;
         atomic_store_explicit(&g_prefs_any_dirty, true,
                               memory_order_release);
         break;
      }
   if(!prefs_notify(vm,notification)) return false;
   RETV();
}

/* Called from the frame pump, and once more when the VM is torn down: the
 * point at which a device's pending apply() has to have reached the disk. */
void dvm_prefs_flush(struct dvm *vm)
{
   if (!vm) return;
   /* The common case is a single atomic load and no lock.  Do not inspect the
    * resizable table until the interpreter lock is ours. */
   if (!atomic_exchange_explicit(&g_prefs_any_dirty, false, memory_order_acq_rel)) return;
   unsigned cookie = dvm_gil_enter_from_guest(vm);
   for (int i = 0; i < g_nprefs; ++i) {
      struct prefs_disk_state *disk = g_prefs[i].disk;
      if (disk && atomic_load_explicit(&disk->failed_generation, memory_order_acquire) &&
          atomic_load_explicit(&disk->saved_generation, memory_order_acquire) < g_prefs[i].generation)
         g_prefs[i].dirty = true;
      if (!g_prefs[i].dirty) continue;
      const uint64_t generation = g_prefs[i].generation;
      const bool saved = prefs_save(vm, g_prefs[i].name, g_prefs[i].map, true);
      if (g_prefs[i].generation == generation) g_prefs[i].dirty = !saved;
   }
   bool any = false;
   for (int i = 0; i < g_nprefs && !any; ++i) any = g_prefs[i].dirty;
   if (any) atomic_store_explicit(&g_prefs_any_dirty, true, memory_order_release);
   dvm_gil_leave_to_guest(vm, cookie);
}

void dvm_prefs_finish(struct dvm *vm)
{
   if (!vm) return;
   dvm_prefs_flush(vm);
   unsigned armd = arm_lock_unlock_all();
   unsigned gild = dvm_gil_unlock_all(vm);
   pthread_mutex_lock(&g_prefs_write_lock);
   while (g_prefs_write_pending)
      pthread_cond_wait(&g_prefs_write_cv, &g_prefs_write_lock);
   pthread_mutex_unlock(&g_prefs_write_lock);
   dvm_gil_relock(vm, gild);
   arm_lock_relock(armd);
}

static bool ed_commit(struct dvm *vm, dvm_ref self,
                      const union dvm_value *args, int nargs,
                      union dvm_value *out)
{
   (void)args; (void)nargs;
   dvm_ref notification=0;
   if(!prefs_publish_editor(vm,self,&notification)) return false;
   bool saved=ed_flush(vm,self);
   if(!prefs_notify(vm,notification)) return false;
   RETI(saved);
}

