         uint64_t ms = due > now ? due - now : 0;
         uint64_t ns = ms > (UINT64_MAX - 1) / 1000000ull
                     ? UINT64_MAX - 1 : ms * 1000000ull;
         if (ns < wait_ns) wait_ns = ns;
