/* --- android.util.SparseArray ------------------------------------------- *
 *
 * An int-keyed map.  It cannot borrow the HashMap storage above, because that
 * compares keys by reference or by string content and two Integer boxes with
 * the same value are neither.  Epic's decoder keeps its outstanding output
 * buffers in one, so a get() that missed would leak every buffer it dequeued.
 */
struct rt_sparse { uint32_t cap, size; struct { int32_t k; dvm_ref v; } e[]; };

static struct rt_sparse *sparse_of(struct dvm *vm, dvm_ref self)
{
   struct dvm_object *o = dvm__obj(vm, self);
   if (!o) return NULL;
   if (!o->data) {
      o->data = calloc(1, sizeof(struct rt_sparse) +
                          8 * sizeof(((struct rt_sparse *)0)->e[0]));
      if (o->data) ((struct rt_sparse *)o->data)->cap = 8;
   }
   return o->data;
}

static int sparse_find(const struct rt_sparse *s, int32_t k)
{
   for (uint32_t i = 0; s && i < s->size; ++i)
      if (s->e[i].k == k) return (int)i;
   return -1;
}

/* The index of `key`, inserting it in key order when it is new: a Sparse*Array
 * keeps its keys ascending, so keyAt()/valueAt() walk them in that order.
 * Returns -1 on allocation failure. */
static int sparse_slot(struct dvm *vm, dvm_ref self, int32_t key)
{
   struct dvm_object *o = dvm__obj(vm, self);
   struct rt_sparse *s = sparse_of(vm, self);
   if (!s || !o) return -1;
   int at = sparse_find(s, key);
   if (at >= 0) return at;
   if (s->size == s->cap) {
      uint32_t cap = s->cap ? s->cap * 2 : 8;
      struct rt_sparse *n = realloc(s, sizeof *n + (size_t)cap * sizeof n->e[0]);
      if (!n) return -1;
      n->cap = cap;
      o->data = s = n;
   }
   uint32_t pos = 0;
   while (pos < s->size && s->e[pos].k < key) ++pos;
   memmove(&s->e[pos + 1], &s->e[pos], (size_t)(s->size - pos) * sizeof s->e[0]);
   ++s->size;
   s->e[pos].k = key;
   s->e[pos].v = 0;
   return (int)pos;
}

static bool sparse_init(struct dvm *vm, dvm_ref self,
                        const union dvm_value *args, int nargs,
                        union dvm_value *out)
{
   (void)args; (void)nargs;
   (void)sparse_of(vm, self);
   RETV();
}

static bool sparse_put(struct dvm *vm, dvm_ref self,
                       const union dvm_value *args, int nargs,
                       union dvm_value *out)
{
   (void)nargs;
   int at = sparse_slot(vm, self, ARG(0).i);
   struct rt_sparse *s = sparse_of(vm, self);
   if (at < 0 || !s) RETV();
   s->e[at].v = ARG(1).l;
   dvm_pin(vm, ARG(1).l);
   RETV();
}

static bool sparse_get(struct dvm *vm, dvm_ref self,
                       const union dvm_value *args, int nargs,
                       union dvm_value *out)
{
   struct rt_sparse *s = sparse_of(vm, self);
   int at = sparse_find(s, ARG(0).i);
   if (at < 0) RETL(nargs > 1 ? ARG(1).l : 0);
   RETL(s->e[at].v);
}

/* The primitive-valued Sparse*Array family.  The key/value store is the same;
 * only the value's type differs, and it rides in the same slot. */
static bool sparse_put_int(struct dvm *vm, dvm_ref self,
                           const union dvm_value *args, int nargs,
                           union dvm_value *out)
{
   /* The value is stored as a raw slot rather than as an object; nothing
    * dereferences it, and pinning a non-reference would corrupt the heap. */
   int at = sparse_slot(vm, self, ARG(0).i);
   struct rt_sparse *sp = sparse_of(vm, self);
   if (at < 0 || !sp) RETV();
   sp->e[at].v = (dvm_ref)(uintptr_t)(nargs > 1 ? ARG(1).j : 0);
   RETV();
}

