/* java.io.File.
 *
 * Only getPath/getParent/getAbsolutePath existed, as host stubs over an opaque
 * handle: bytecode could not even construct one, so `new File(dir, name)` threw
 * and every exists()/mkdirs() probe was a miss that answered false.  Java code
 * that checks for its own cache or download directory concluded the storage was
 * unusable.  Back it with the path string and answer from the host filesystem —
 * the guest paths are already mapped there. */
/* Context.getCacheDir() and friends are answered by the host stub layer, which
 * hands back an opaque File handle with the path recorded beside it.  Such an
 * object reaches bytecode as an external wrapper, not as one of these, so read
 * through to that path rather than reporting the empty string — otherwise
 * `new File(getCacheDir(), "volley")` loses the directory it was rooted at. */
static const char *file_path(struct dvm *vm, dvm_ref self)
{
   union dvm_value v = { 0 };
   if (dvm_get_field(vm, self, "path", "Ljava/lang/String;", &v) && v.l) {
      const char *s = dvm_string_utf8(vm, v.l);
      if (s && *s) return s;
   }
   uint32_t host = dvm_external_handle(vm, self);
   return host ? jni_file_get_path((jobject)(uintptr_t)host) : NULL;
}

/* The same path, resolved into the host filesystem.
 *
 * file_path() answers what the app called the file — that is what getPath()
 * and friends have to return.  Everything that actually opens, stats, renames
 * or deletes needs the other one: an Android path names a directory in the
 * guest's filesystem, and handing it to the host unchanged makes it name this
 * machine's instead.  The game's patcher renames a staged directory into
 * place, and with the guest namespace missing that ran against the host's /etc.
 *
 * The results rotate through a small bank of buffers because renameTo() holds
 * two of them live at once. */
static const char *file_host_path(struct dvm *vm, dvm_ref self)
{
   /* java.io constructors accept either File or String.  Both name the
    * guest filesystem and must pass through the same namespace mapping. */
   const char *p = object_is_a(vm, self, "Ljava/lang/String;")
      ? dvm_string_utf8(vm, self) : file_path(vm, self);
   if (!p || !*p) return p;
   static char bank[4][DVM_PATH_MAX];
   static int next;
   char *buf = bank[next];
   next = (next + 1) % 4;
   return arm_exec_map_guest_path(p, buf, DVM_PATH_MAX);
}

static bool file_init(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                      int nargs, union dvm_value *out)
{
   (void)out;
   char joined[DVM_PATH_MAX];
   /* dvm_string_utf8() stringifies arbitrary objects, so trying it first on
    * File(File,String) produced "java/io/File@..." instead of the parent's
    * path.  Select by Java type before converting. */
   const bool parent_is_file = ARG(0).l &&
      object_is_a(vm, ARG(0).l, "Ljava/io/File;");
   const char *a = parent_is_file ? file_path(vm, ARG(0).l)
                                  : (ARG(0).l ? dvm_string_utf8(vm, ARG(0).l)
                                              : NULL);
   const char *b = (nargs > 1 && ARG(1).l) ? dvm_string_utf8(vm, ARG(1).l) : NULL;
   /* Unix FileSystem.resolve: an empty parent yields the child alone.  Joining
    * with '/' turned `new File("", "Metadata")` into `/Metadata` and Unity's
    * IL2CPP extract wrote Managed trees onto the host root. */
   if (a && *a && b) {
      size_t n = strlen(a);
      /* An absolute child is still a child — java.io.File pastes it under the
       * parent — but on a device "absolute" means the device's own tree, and
       * here it means the host's.  Pasting one of our directories under
       * another repeats the whole data root inside the name
       * (".../cache//var/lunaria/data/<pkg>/no_backup/x").  Nothing reads
       * those names, but they are what the app then opens, prints and hashes,
       * and DVM_PATH_MAX is finite.  Keep the child relative to the root it
       * already names. */
      const char *child = b;
      if (child[0] == '/') {
         /* Strip the deepest of our own roots the child already names: the
          * package's own directory first (".../data/<pkg>"), then the data
          * root.  What is left is the part that actually distinguishes the
          * file. */
         const char *files = getenv("ANDROID_FILES_DIR");
         char pkgdir[DVM_PATH_MAX];
         const char *roots[2] = { NULL, getenv("LUNARIA_DATA_ROOT") };
         if (files && *files) {
            snprintf(pkgdir, sizeof pkgdir, "%s", files);
            char *slash = strrchr(pkgdir, '/');
            if (slash && slash != pkgdir) { *slash = '\0'; roots[0] = pkgdir; }
         }
         for (int i = 0; i < 2; ++i) {
            const char *root = roots[i];
            size_t rlen = root ? strlen(root) : 0u;
            while (rlen && root[rlen - 1] == '/') --rlen;
            if (rlen && strncmp(child, root, rlen) == 0 && child[rlen] == '/') {
               child += rlen;
               break;
            }
         }
         while (child[0] == '/' && child[1] == '/') ++child;
      }
      snprintf(joined, sizeof joined, "%s%s%s", a,
               (n && a[n - 1] == '/') ? "" :
                  (child[0] == '/' ? "" : "/"), child);
   } else if (b) {
      snprintf(joined, sizeof joined, "%s", b);
   } else {
      snprintf(joined, sizeof joined, "%s", a ? a : "");
   }
   union dvm_value v = { 0 };
   v.l = dvm_new_string(vm, joined);
   (void)dvm_set_field(vm, self, "path", "Ljava/lang/String;", v);
   RETV();
}

static bool file_getPath(struct dvm *vm, dvm_ref self,
                         const union dvm_value *args, int nargs,
                         union dvm_value *out)
{
   (void)args; (void)nargs;
   const char *p = file_path(vm, self);
   static unsigned traced;
   if (traced++ < 12) {
      uint32_t host = dvm_external_handle(vm, self);
      fprintf(stderr, "[dvm_file] getPath self=0x%x host=0x%x path=%s\n",
              self, host, p ? p : "(null)");
   }
   /* A constructed File always has a path string on Android — never null.
    * Returning null made String.valueOf / StringBuilder.append render the
    * literal "null" into paths such as "…nullpush_ids". */
   RETL(dvm_new_string(vm, p ? p : ""));
}

static bool file_getName(struct dvm *vm, dvm_ref self,
                         const union dvm_value *args, int nargs,
                         union dvm_value *out)
{
   (void)args; (void)nargs;
   const char *p = file_path(vm, self);
   if (!p) RETL(0);
   const char *slash = strrchr(p, '/');
   RETL(dvm_new_string(vm, slash ? slash + 1 : p));
}

static bool file_getParent(struct dvm *vm, dvm_ref self,
                           const union dvm_value *args, int nargs,
                           union dvm_value *out)
{
   (void)args; (void)nargs;
   const char *p = file_path(vm, self);
   const char *slash = p ? strrchr(p, '/') : NULL;
   if (!slash) RETL(0);
   /* Parent of `/Metadata` is `/`, not null — Java keeps the root. */
   if (slash == p) RETL(dvm_new_string(vm, "/"));
   RETL(dvm_new_string_n(vm, p, (size_t)(slash - p)));
}

static bool file_getParentFile(struct dvm *vm, dvm_ref self,
                               const union dvm_value *args, int nargs,
                               union dvm_value *out)
{
   union dvm_value parent = { 0 };
   if (!file_getParent(vm, self, args, nargs, &parent) || !parent.l) RETL(0);
   struct dvm_class *c = dvm__class_by_desc(vm, "Ljava/io/File;");
   dvm_ref f = c ? dvm_new_object(vm, c) : 0;
   if (!f) RETL(0);
   (void)dvm_set_field(vm, f, "path", "Ljava/lang/String;", parent);
   RETL(f);
}

static bool file_stat_is(struct dvm *vm, dvm_ref self, int want_dir, int want_any,
                         union dvm_value *out)
{
   const char *p = file_host_path(vm, self);
   struct stat st;
   if (!p || !*p || luna_file_stat_follow(p, &st) != 0) RETI(0);
   if (want_any) RETI(1);
   RETI(want_dir ? S_ISDIR(st.st_mode) : S_ISREG(st.st_mode));
}

