/* File.setLastModified(long): Android returns whether the underlying
 * utimensat/utime succeeded.  Crashlytics (and others) call this after
 * writing a report; answering unresolved→0 left the file's mtime as the
 * create time and made age-based cleanup keep stale reports forever. */
static bool file_setLastModified(struct dvm *vm, dvm_ref self,
                                 const union dvm_value *args, int nargs,
                                 union dvm_value *out)
{
   (void)nargs;
   const char *p = file_host_path(vm, self);
   if (!p || !*p) RETI(0);
   int64_t ms = ARG(0).j;
   if (ms < 0) RETI(0);
   RETI(luna_file_set_modified(p, ms) == 0 ? 1 : 0);
}

/* mkdirs() creates the whole chain; luna_file_mkdir() only the leaf. */
static bool file_mkdir_impl(struct dvm *vm, dvm_ref self, bool parents,
                            union dvm_value *out)
{
   const char *p = file_host_path(vm, self);
   if (!p || !*p) RETI(0);
   char buf[DVM_PATH_MAX];
   snprintf(buf, sizeof buf, "%s", p);
   if (parents) {
      for (char *q = buf + 1; *q; ++q) {
         if (*q != '/') continue;
         *q = '\0';
         (void)luna_file_mkdir(buf, 0777);
         *q = '/';
      }
   }
   if (luna_file_mkdir(buf, 0777) == 0) RETI(1);
   struct stat st;
   RETI(errno == EEXIST && luna_file_stat_follow(buf, &st) == 0 && S_ISDIR(st.st_mode));
}

static bool file_mkdir(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                       int nargs, union dvm_value *out)
{ (void)args; (void)nargs; return file_mkdir_impl(vm, self, false, out); }
static bool file_mkdirs(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                        int nargs, union dvm_value *out)
{ (void)args; (void)nargs; return file_mkdir_impl(vm, self, true, out); }

static bool file_delete(struct dvm *vm, dvm_ref self, const union dvm_value *args,
                        int nargs, union dvm_value *out)
{
   (void)args; (void)nargs;
   const char *p = file_host_path(vm, self);
   if (p) arm_exec_note_destructive("File.delete", p, NULL);
   if (!p || !*p) RETI(0);
   RETI(remove(p) == 0);
}

static bool file_createNewFile(struct dvm *vm, dvm_ref self,
                               const union dvm_value *args, int nargs,
                               union dvm_value *out)
{
   (void)args; (void)nargs;
   const char *p = file_host_path(vm, self);
   if (!p || !*p) RETI(0);
   int fd = luna_file_open(p, O_CREAT | O_EXCL | O_WRONLY, 0666);
   if (fd >= 0) { luna_fd_close(fd); RETI(1); }
   if (errno == EEXIST) RETI(0);
   dvm__throw(vm, "java/io/IOException", "%s: %s", p, strerror(errno));
   return false;
}

/* File.createTempFile(prefix, suffix, directory).  Several Android SDKs use
 * this as the durable-write staging step (write, fsync, rename).  Returning
 * null here made Firebase Installations send an auth request for installation
 * "null", even though the network stack itself was working. */
static bool file_createTempFile(struct dvm *vm, dvm_ref self,
                                const union dvm_value *args, int nargs,
                                union dvm_value *out)
{
   (void)self;
   const char *prefix = nargs > 0 ? dvm_string_utf8(vm, ARG(0).l) : NULL;
   const char *suffix = nargs > 1 && ARG(1).l
                           ? dvm_string_utf8(vm, ARG(1).l) : ".tmp";
   const char *directory = nargs > 2 && ARG(2).l
                              ? file_path(vm, ARG(2).l) : NULL;
   if (!prefix || strlen(prefix) < 3) {
      dvm__throw(vm, "java/lang/IllegalArgumentException",
                 "Prefix string too short");
      return false;
   }
   if (!directory || !*directory) directory = "/tmp";

   char guest[DVM_PATH_MAX];
   snprintf(guest, sizeof guest, "%s%s%sXXXXXX%s", directory,
            directory[strlen(directory) - 1] == '/' ? "" : "/",
            prefix, suffix ? suffix : ".tmp");
   char host[DVM_PATH_MAX];
   const char *mapped = arm_exec_map_guest_path(guest, host, sizeof host);
   if (!mapped) {
      dvm__throw(vm, "java/io/IOException", "%s: invalid path", guest);
      return false;
   }
   /* The mapping answers with the input itself when the path needs no
    * rewriting; mkstemps() edits its template in place, so it has to be the
    * writable copy either way. */
   if (mapped != host) snprintf(host, sizeof host, "%s", mapped);
   int suffix_len = (int)strlen(suffix ? suffix : ".tmp");
   int fd = luna_file_mkstemps(host, suffix_len);
   if (fd < 0) {
      dvm__throw(vm, "java/io/IOException", "%s: %s", guest,
                 strerror(errno));
      return false;
   }
   luna_fd_close(fd);

   /* mkstemps changed the host spelling in place.  The guest and host paths
    * have the same tail, so copy the generated six characters back. */
   size_t hn = strlen(host), gn = strlen(guest);
   if (hn >= (size_t)suffix_len + 6 && gn >= (size_t)suffix_len + 6)
      memcpy(guest + gn - (size_t)suffix_len - 6,
             host + hn - (size_t)suffix_len - 6, 6);
   struct dvm_class *c = dvm__class_by_desc(vm, "Ljava/io/File;");
   dvm_ref file = c ? dvm_new_object(vm, c) : 0;
   if (!file) RETL(0);
   union dvm_value path = { .l = dvm_new_string(vm, guest) };
   (void)dvm_set_field(vm, file, "path", "Ljava/lang/String;", path);
   RETL(file);
}

/* File.renameTo() — the commit step of every write-to-temp-then-swap on
 * Android.  Without it Crashlytics' QueueFile could not install the file it
 * had just built ("Rename failed!") and reported a null queue for the rest of
 * the run. */
static bool file_renameTo(struct dvm *vm, dvm_ref self,
                          const union dvm_value *args, int nargs,
                          union dvm_value *out)
{
   const char *from = file_host_path(vm, self);
   const char *to = (nargs > 0 && ARG(0).l) ? file_host_path(vm, ARG(0).l) : NULL;
   if (!from || !*from || !to || !*to) RETI(0);
   arm_exec_note_destructive("File.renameTo", from, to);
   RETI(luna_file_rename(from, to) == 0);
}

