/* java.util.Objects.requireNonNull preserves object identity.  Treating an
 * unresolved generic return as zero silently turns every valid reference that
 * passes through it into null, with the failure surfacing at an unrelated call
 * site one instruction later. */
static bool objects_requireNonNull(struct dvm *vm, dvm_ref self,
                                   const union dvm_value *args, int nargs,
                                   union dvm_value *out)
{
   (void)self;
   if (nargs < 1 || !ARG(0).l) {
      const char *message = (nargs >= 2 && ARG(1).l)
                          ? dvm_string_utf8(vm, ARG(1).l) : NULL;
      dvm__throw(vm, "java/lang/NullPointerException", "%s",
                 message ? message : "null");
      return false;
   }
   RETL(ARG(0).l);
}

/* Objects.equals(a, b): null-safe reference equality, then Object.equals.
 * Missing this made every Collections/Map probe that went through it throw
 * unresolved and abort the surrounding init. */
static bool objects_equals(struct dvm *vm, dvm_ref self,
                           const union dvm_value *args, int nargs,
                           union dvm_value *out)
{
   (void)self;
   if (nargs < 2) RETI(0);
   RETI(key_eq(vm, ARG(0).l, ARG(1).l) ? 1 : 0);
}

static bool objects_toString_default(struct dvm *vm, dvm_ref self,
                                     const union dvm_value *args, int nargs,
                                     union dvm_value *out)
{
   if (!ARG(0).l) RETL(ARG(1).l);
   return s_valueOf_obj(vm, self, args, nargs, out);
}

