      if (!object_is_a(vm, ARG(0).l, "Ljava/util/List;")) RETI(0);
      struct dvm_class *c = dvm_object_class(vm, ARG(0).l);
      struct dvm_method *size = dvm_find_method(vm, c, "size", "()I");
      union dvm_value n = { 0 };
