   union dvm_value one = { .l = x }, str = { 0 };
   if (!s_valueOf_obj(vm, 0, &one, 1, &str)) return false;
   size_t n = 0;
   const char *s = str.l ? sdata(vm, str.l, &n) : NULL;
   if (!s) { s = "null"; n = 4; }
