static bool tu_indexOf(struct dvm *vm, dvm_ref self,
                       const union dvm_value *args, int nargs,
                       union dvm_value *out)
{
   (void)self;
   dvm_ref cs = ARG(0).l;
   int32_t ch = ARG(1).i;
   const char *s = dvm_string_utf8(vm, cs);
   if (!s) RETI(-1);
   /* indexOf(seq, ch), indexOf(seq, ch, start) and indexOf(seq, ch, start,
    * end) are three entry points into the same search; the shorter ones just
    * leave the window open at that end. */
   int32_t start = nargs > 2 ? ARG(2).i : 0;
   int32_t end   = nargs > 3 ? ARG(3).i : INT32_MAX;
   if (start < 0) start = 0;
   int32_t i = 0;
   for (const unsigned char *p = (const unsigned char *)s; *p; ) {
      unsigned cp;
      if (*p < 0x80) { cp = *p++; }
      else if ((*p & 0xe0) == 0xc0) { cp = (*p & 0x1f) << 6 | (p[1] & 0x3f); p += 2; }
      else if ((*p & 0xf0) == 0xe0) {
         cp = (*p & 0x0f) << 12 | (p[1] & 0x3f) << 6 | (p[2] & 0x3f); p += 3;
      } else { p += 4; ++i; continue; }
      if (i >= start && i < end && (int32_t)cp == ch) RETI(i);
      ++i;
      if (i >= end) break;
   }
   RETI(-1);
}

/* TextUtils.getCapsMode(cs, off, reqModes) — which of the auto-capitalisation
 * modes apply at `off`, restricted to the ones the caller asked about.  An
 * IME connection calls this on every keystroke to decide the shift state; the
 * unresolved stub answered 0, which reads as "never capitalise". */
#define DVM_CAP_MODE_CHARACTERS 0x00001000
#define DVM_CAP_MODE_WORDS      0x00002000
#define DVM_CAP_MODE_SENTENCES  0x00004000

static bool tu_getCapsMode(struct dvm *vm, dvm_ref self,
                           const union dvm_value *args, int nargs,
                           union dvm_value *out)
{
   (void)self; (void)nargs;
   int32_t off = ARG(1).i, req = ARG(2).i;
   if (off < 0) RETI(0);
   int32_t mode = req & DVM_CAP_MODE_CHARACTERS;
   if ((req & (DVM_CAP_MODE_WORDS | DVM_CAP_MODE_SENTENCES)) == 0) RETI(mode);

   size_t len = 0;
   const char *cs = sdata(vm, ARG(0).l, &len);
   if (!cs) RETI(mode);
   if ((size_t)off > len) off = (int32_t)len;

   /* Step back over opening punctuation, then over spaces and tabs.  What is
    * left is the character that decides the answer. */
   int32_t i = off;
   while (i > 0) {
      char c = cs[i - 1];
      if (c != '"' && c != '\'' && c != '(' && c != '[' && c != '{') break;
      --i;
   }
   int32_t j = i;
   while (j > 0 && (cs[j - 1] == ' ' || cs[j - 1] == '\t')) --j;

   /* Start of the text or of a paragraph: both a word and a sentence begin. */
   if (j == 0 || cs[j - 1] == '\n')
      RETI(mode | (req & (DVM_CAP_MODE_WORDS | DVM_CAP_MODE_SENTENCES)));

   /* A word begins wherever whitespace was skipped over. */
   if (j != i || (i > 0 && (cs[i - 1] == ' ' || cs[i - 1] == '\t')))
      mode |= req & DVM_CAP_MODE_WORDS;
   else
      RETI(mode);   /* mid-word: neither a new word nor a new sentence */

   /* A sentence begins after '.', '?' or '!' (with their closing punctuation),
    * but only when whitespace separated it from `off`. */
   int32_t k = j;
   while (k > 0) {
      char c = cs[k - 1];
      if (c != '"' && c != '\'' && c != ')' && c != ']' && c != '}') break;
      --k;
   }
   if (k > 0) {
      char c = cs[k - 1];
      if (c == '.' || c == '?' || c == '!') mode |= req & DVM_CAP_MODE_SENTENCES;
   }
   RETI(mode);
}

/* TextUtils.indexOf(haystack, needle[, start]) — the substring overloads.
 * Indices are in chars; the VM keeps strings as UTF-8 and treats each byte
 * below 0x80 as one char, which is what every caller here searches for. */
static bool tu_indexOf_seq(struct dvm *vm, dvm_ref self,
                           const union dvm_value *args, int nargs,
                           union dvm_value *out)
{
   (void)self;
   size_t hn = 0, nn = 0;
   const char *hay = sdata(vm, ARG(0).l, &hn);
   const char *needle = sdata(vm, ARG(1).l, &nn);
   if (!hay || !needle) RETI(-1);
   int32_t start = nargs >= 3 ? ARG(2).i : 0;
   if (start < 0) start = 0;
   if ((size_t)start > hn) RETI(-1);
   if (nn > hn - (size_t)start) RETI(-1);
   for (size_t i = (size_t)start; i + nn <= hn; ++i)
      if (!memcmp(hay + i, needle, nn)) RETI((int32_t)i);
   RETI(-1);
}

/* Policies are immutable snapshots. Store them on the guest Thread, so
 * callbacks and interpreter workers do not share a host-global policy. */
static dvm_ref sm_policy(struct dvm *vm, int32_t mask)
{
   struct dvm_class *c = dvm__class_by_desc(vm, "Landroid/os/StrictMode$ThreadPolicy;");
   dvm_ref policy = c ? dvm_new_object(vm, c) : 0;
   if (!policy) {
      dvm__throw(vm, "java/lang/OutOfMemoryError", "thread policy");
      return 0;
   }
   union dvm_value v = { .i = mask };
   (void)dvm_set_field(vm, policy, "mask", "I", v);
   return policy;
}

static bool sm_thread_policy(struct dvm *vm, dvm_ref self,
                              const union dvm_value *args, int nargs,
                              union dvm_value *out)
{
   (void)self; (void)nargs;
   dvm_ref thread = dvm__current_thread(vm);
   const struct dvm_method *m = dvm__builtin_method();
   if (m && !strcmp(m->name, "setThreadPolicy")) {
      if (!ARG(0).l) {
         dvm__throw(vm, "java/lang/NullPointerException", "null thread policy");
         return false;
      }
      (void)dvm_set_field(vm, thread, "strictPolicy", "Landroid/os/StrictMode$ThreadPolicy;", ARG(0));
      RETV();
   }
   union dvm_value policy = { 0 }, mask = { 0 };
   (void)dvm_get_field(vm, thread, "strictPolicy", "Landroid/os/StrictMode$ThreadPolicy;", &policy);
   if (!policy.l) {
      policy.l = sm_policy(vm, 0);
      if (!policy.l) return false;
      (void)dvm_set_field(vm, thread, "strictPolicy", "Landroid/os/StrictMode$ThreadPolicy;", policy);
   }
   if (m && strncmp(m->name, "allow", 5) == 0) {
      (void)dvm_get_field(vm, policy.l, "mask", "I", &mask);
      int32_t disabled = !strcmp(m->name, "allowThreadDiskWrites") ? 3 : 2;
      if (mask.i & disabled) {
         union dvm_value relaxed = { .l = sm_policy(vm, mask.i & ~disabled) };
         if (!relaxed.l) return false;
         (void)dvm_set_field(vm, thread, "strictPolicy", "Landroid/os/StrictMode$ThreadPolicy;", relaxed);
      }
   }
   RETL(policy.l);
}

static bool sm_builder(struct dvm *vm, dvm_ref self,
                        const union dvm_value *args, int nargs,
                        union dvm_value *out)
{
   const struct dvm_method *m = dvm__builtin_method();
   const char *name = m ? m->name : "";
   union dvm_value mask = { 0 };
   (void)dvm_get_field(vm, self, "mask", "I", &mask);
   if (!strcmp(name, "<init>")) {
      mask.i = 0;
      if (nargs) {
         if (!ARG(0).l) {
            dvm__throw(vm, "java/lang/NullPointerException", "null thread policy");
            return false;
         }
         (void)dvm_get_field(vm, ARG(0).l, "mask", "I", &mask);
      }
      (void)dvm_set_field(vm, self, "mask", "I", mask);
      RETV();
   }
   if (!strcmp(name, "build")) {
      if (mask.i && !(mask.i & (int32_t)UINT32_C(0xffff0000))) mask.i |= 1 << 30;
      dvm_ref policy = sm_policy(vm, mask.i);
      if (!policy) return false;
      RETL(policy);
   }
   if (!strcmp(name, "detectAll")) {
      int sdk = lunaria_app_target_sdk();
      mask.i |= 7;
      if (sdk >= 11) mask.i |= 8;
      if (sdk >= 23) mask.i |= 16;
      if (sdk >= 26) mask.i |= 32;
   } else if (!strcmp(name, "permitAll")) mask.i &= ~0xffff;
   else if (!strcmp(name, "penaltyLog")) mask.i |= 1 << 30;
   else {
      int32_t bit = 0;
      const char *kind = name + 6;
      if (!strcmp(kind, "DiskWrites")) bit = 1;
      else if (!strcmp(kind, "DiskReads")) bit = 2;
      else if (!strcmp(kind, "Network")) bit = 4;
      else if (!strcmp(kind, "CustomSlowCalls")) bit = 8;
      else if (!strcmp(kind, "ResourceMismatches")) bit = 16;
      else if (!strcmp(kind, "UnbufferedIo")) bit = 32;
      if (!strncmp(name, "permit", 6)) mask.i &= ~bit;
      else mask.i |= bit;
   }
   (void)dvm_set_field(vm, self, "mask", "I", mask);
   RETL(self);
}

