/* Resolve an installed manifest provider by authority.  The native APK launcher has
 * already decoded the binary manifest into the same provider table used by
 * loader.c to start providers, so PackageManager must expose that table too;
 * returning null here made FileProvider reject metadata that had in fact been
 * parsed and attached correctly a few instructions earlier. */
static bool pm_resolveProvider(struct dvm *vm, dvm_ref self,
                               const union dvm_value *args, int nargs,
                               union dvm_value *out)
{
   (void)self; (void)nargs;
   const char *wanted = dvm_string_utf8(vm, ARG(0).l);
   const char *encoded = getenv("ANDROID_CONTENT_PROVIDERS");
   char *providers = wanted && encoded ? strdup(encoded) : NULL;
   if (!providers) RETL(0);

   dvm_ref result = 0;
   char *save = NULL;
   for (char *entry = strtok_r(providers, ";", &save); entry;
        entry = strtok_r(NULL, ";", &save)) {
      char *authority = strchr(entry, '|');
      if (authority) *authority++ = '\0';
      char *metadata = authority ? strchr(authority, '|') : NULL;
      if (metadata) *metadata++ = '\0';
      if (!authority || strcmp(authority, wanted)) continue;

      result = pm_component_info(vm, "Landroid/content/pm/ProviderInfo;");
      if (!result) break;
      union dvm_value value = { .l = dvm_new_string(vm, authority) };
      (void)dvm_set_field(vm, result, "authority", "Ljava/lang/String;", value);
      value.l = dvm_new_string(vm, entry);
      (void)dvm_set_field(vm, result, "name", "Ljava/lang/String;", value);
      const char *package_name = getenv("ANDROID_PACKAGE_NAME");
      value.l = dvm_new_string(vm, package_name ? package_name : "");
      (void)dvm_set_field(vm, result, "packageName", "Ljava/lang/String;", value);
      value.i = 1;
      (void)dvm_set_field(vm, result, "grantUriPermissions", "Z", value);

      union dvm_value bundle = { 0 };
      (void)dvm_get_field(vm, result, "metaData", "Landroid/os/Bundle;", &bundle);
      if (vm->trace)
         fprintf(stderr, "[dvm] provider metadata bundle=@%x text=%s\n",
                 bundle.l, metadata ? metadata : "");
      char *meta_save = NULL;
      for (char *pair = metadata ? strtok_r(metadata, ",", &meta_save) : NULL;
           pair; pair = strtok_r(NULL, ",", &meta_save)) {
         char *text = strchr(pair, '~');
         if (!text || !bundle.l) continue;
         *text++ = '\0';
         char *end = NULL;
         long integer = strtol(text, &end, 0);
         union dvm_value put_args[2] = {
            { .l = dvm_new_string(vm, pair) }, { 0 }
         }, ignored = { 0 };
         if (end && *end == '\0') {
            put_args[1].i = (int32_t)integer;
            (void)bundle_putInt(vm, bundle.l, put_args, 2, &ignored);
            if (vm->trace) {
               union dvm_value check = { 0 };
               (void)bundle_getInt(vm, bundle.l, put_args, 1, &check);
               fprintf(stderr, "[dvm] provider metadata %s=%ld -> %d\n",
                       pair, integer, check.i);
            }
         } else {
            put_args[1].l = dvm_new_string(vm, text);
            (void)bundle_putString(vm, bundle.l, put_args, 2, &ignored);
         }
      }
      if (vm->trace)
         fprintf(stderr, "[dvm] PackageManager resolved provider %s (%s)\n",
                 authority, entry);
      break;
   }
   free(providers);
   RETL(result);
}

/* GET_META_DATA.  Without it, ServiceInfo.metaData stays the empty bundle
 * pm_component_info() already installed — the same as a device. */
enum { PM_GET_META_DATA = 0x00000080 };

/* The component named by args[0], with its own manifest <meta-data> when
 * the caller asked for it.  Firebase ComponentDiscovery reads
 * ComponentDiscoveryService this way and will not register
 * FirebaseMessagingRegistrar from any other bundle. */
static dvm_ref pm_info_for_component(struct dvm *vm, const char *desc,
                                     const union dvm_value *args, int nargs)
{
   dvm_ref info = pm_component_info(vm, desc);
   if (!info || nargs < 1 || !ARG(0).l) return info;
   union dvm_value cls = { 0 };
   (void)dvm_get_field(vm, ARG(0).l, "cls", "Ljava/lang/String;", &cls);
   const char *name = dvm_string_utf8(vm, cls.l);
   if (!name || !*name) return info;
   union dvm_value v = { .l = dvm_new_string(vm, name) };
   (void)dvm_set_field(vm, info, "name", "Ljava/lang/String;", v);
   const char *pkg = getenv("ANDROID_PACKAGE_NAME");
   v.l = dvm_new_string(vm, pkg ? pkg : "");
   (void)dvm_set_field(vm, info, "packageName", "Ljava/lang/String;", v);
   if (nargs > 1 && (ARG(1).i & PM_GET_META_DATA)) {
      union dvm_value bundle = { 0 };
      (void)dvm_get_field(vm, info, "metaData", "Landroid/os/Bundle;", &bundle);
      manifest_bundle_fill(vm, bundle.l, arm_exec_apk_component_meta_keys(name));
   }
   return info;
}

static dvm_ref pm_package_info(struct dvm *, const struct lunaria_android_package *, uint32_t);

/* getServiceInfo(): a service this package declares, with the enabled and
 * exported state its manifest gives it.  A class the manifest does not list is
 * not a component, whatever the dex holds. */
static bool pm_getServiceInfo(struct dvm *vm, dvm_ref self,
                              const union dvm_value *args, int nargs,
                              union dvm_value *out)
{
   (void)self;
   if (!ARG(0).l) {
      dvm__throw(vm, "java/lang/NullPointerException", "null component"); return false;
   }
   union dvm_value pkg = { 0 }, cls = { 0 };
   (void)dvm_get_field(vm, ARG(0).l, "pkg", "Ljava/lang/String;", &pkg);
   (void)dvm_get_field(vm, ARG(0).l, "cls", "Ljava/lang/String;", &cls);
   const char *package = dvm_string_utf8(vm, pkg.l), *name = dvm_string_utf8(vm, cls.l);
   const char *current = getenv("ANDROID_PACKAGE_NAME"), *table = getenv("ANDROID_SERVICES");
   struct lunaria_android_package record;
   if (!package || !name || !current || strcmp(package, current) ||
       !lunaria_android_package_find(package, &record)) goto missing;
   uint32_t flags = (uint32_t)ARG(1).i;
   char *rows = strdup(table ? table : "");
   if (!rows) { dvm__throw(vm, "java/lang/OutOfMemoryError", "service lookup"); return false; }
   char *scan = rows, *row;
   dvm_ref info = 0;
   while ((row = luna_strsep(&scan, ";"))) {
      char *parts[4];
      for (int i = 0; i < 4; ++i) parts[i] = luna_strsep(&row, "|");
      if (!parts[2] || strcmp(parts[0], name)) continue;
      bool enabled = atoi(parts[1]) != 0;
      if (!(flags & 0x00000200u) && !enabled) break;
      info = pm_info_for_component(vm, "Landroid/content/pm/ServiceInfo;", args, nargs);
      if (!info) break;
      union dvm_value v = { .i = enabled };
      (void)dvm_set_field(vm, info, "enabled", "Z", v);
      v.i = atoi(parts[2]) > 0 || (atoi(parts[2]) < 0 && parts[3] && *parts[3]);
      (void)dvm_set_field(vm, info, "exported", "Z", v);
      v.l = dvm_new_string(vm, current);
      (void)dvm_set_field(vm, info, "processName", "Ljava/lang/String;", v);
      dvm_ref pi = pm_package_info(vm, &record, 0);
      union dvm_value app = { 0 };
      if (pi) (void)dvm_get_field(vm, pi, "applicationInfo", "Landroid/content/pm/ApplicationInfo;", &app);
      (void)dvm_set_field(vm, info, "applicationInfo", "Landroid/content/pm/ApplicationInfo;", app);
      if (!(flags & PM_GET_META_DATA)) {
         v.l = 0;
         (void)dvm_set_field(vm, info, "metaData", "Landroid/os/Bundle;", v);
      }
      break;
   }
   free(rows);
   if (info) RETL(info);
missing:
   dvm__throw(vm, "android/content/pm/PackageManager$NameNotFoundException", "%s/%s",
              package ? package : "", name ? name : "");
   return false;
}

static bool pm_getReceiverInfo(struct dvm *vm, dvm_ref self,
                               const union dvm_value *args, int nargs,
                               union dvm_value *out)
{
   (void)self;
   if (!ARG(0).l) {
      dvm__throw(vm, "java/lang/NullPointerException", "null component"); return false;
   }
   union dvm_value pkg = { 0 }, cls = { 0 };
   (void)dvm_get_field(vm, ARG(0).l, "pkg", "Ljava/lang/String;", &pkg);
   (void)dvm_get_field(vm, ARG(0).l, "cls", "Ljava/lang/String;", &cls);
   const char *package = dvm_string_utf8(vm, pkg.l), *name = dvm_string_utf8(vm, cls.l);
   const char *current = getenv("ANDROID_PACKAGE_NAME"), *table = getenv("ANDROID_RECEIVERS");
   struct lunaria_android_package record;
   if (!package || !name || !current || strcmp(package, current) ||
       !lunaria_android_package_find(package, &record)) goto missing;
   uint32_t flags = (uint32_t)ARG(1).i;
   if ((flags & 0x00100000u) && !(record.flags & 1)) goto missing;
   char *rows = strdup(table ? table : "");
   if (!rows) { dvm__throw(vm, "java/lang/OutOfMemoryError", "receiver lookup"); return false; }
   char *scan = rows, *row;
   dvm_ref info = 0;
   while ((row = luna_strsep(&scan, ";"))) {
      char *parts[7];
      for (int i = 0; i < 7; ++i) parts[i] = luna_strsep(&row, "|");
      if (!parts[6] || strcmp(parts[0], name)) continue;
      bool enabled = atoi(parts[1]) != 0, app_enabled = atoi(parts[2]) != 0;
      bool aware = atoi(parts[4]) != 0;
      if (!(flags & 0x00000200u) && (!enabled || !app_enabled)) break;
      uint32_t boot_flags = flags & 0x000c0000u;
      if (boot_flags && !(boot_flags & (aware ? 0x00080000u : 0x00040000u))) break;
      info = pm_info_for_component(vm, "Landroid/content/pm/ActivityInfo;", args, nargs);
      if (!info) break;
      union dvm_value v = { .i = enabled };
      (void)dvm_set_field(vm, info, "enabled", "Z", v);
      v.i = atoi(parts[3]) != 0;
      (void)dvm_set_field(vm, info, "exported", "Z", v);
      v.i = aware;
      (void)dvm_set_field(vm, info, "directBootAware", "Z", v);
      v.l = *parts[5] ? dvm_new_string(vm, parts[5]) : 0;
      (void)dvm_set_field(vm, info, "permission", "Ljava/lang/String;", v);
      v.l = dvm_new_string(vm, parts[6]);
      (void)dvm_set_field(vm, info, "processName", "Ljava/lang/String;", v);
      dvm_ref pi = pm_package_info(vm, &record, 0);
      union dvm_value app = { 0 };
      if (pi) (void)dvm_get_field(vm, pi, "applicationInfo", "Landroid/content/pm/ApplicationInfo;", &app);
      (void)dvm_set_field(vm, info, "applicationInfo", "Landroid/content/pm/ApplicationInfo;", app);
      v.i = app_enabled;
      if (app.l) (void)dvm_set_field(vm, app.l, "enabled", "Z", v);
      if (!(flags & PM_GET_META_DATA)) {
         v.l = 0;
         (void)dvm_set_field(vm, info, "metaData", "Landroid/os/Bundle;", v);
      }
      if (vm->trace) fprintf(stderr, "[dvm] receiver %s enabled=%d exported=%d\n", name, enabled, atoi(parts[3]) != 0);
      break;
   }
   free(rows);
   if (info) RETL(info);
missing:
   dvm__throw(vm, "android/content/pm/PackageManager$NameNotFoundException", "%s/%s",
              package ? package : "", name ? name : "");
   return false;
}

