/* The database object Context.openOrCreateDatabase() hands back.  It is the
 * same shape SQLiteOpenHelper builds — an object whose `path` names the file —
 * so anything that reaches the database either way agrees on which one it is. */
static bool context_open_database(struct dvm *vm, dvm_ref self,
                                  const union dvm_value *args, int nargs,
                                  union dvm_value *out)
{
   (void)self; (void)nargs;
   const char *name = ARG(0).l ? dvm_string_utf8(vm, ARG(0).l) : NULL;
   char path[1024];
   dvm_sqlite_database_path(name && *name ? name : "default.db", path, sizeof path);
   /* MODE_ENABLE_WRITE_AHEAD_LOGGING = 0x8 */
   const int flags = 0x10000000 | ((ARG(1).i & 0x8) ? 0x20000000 : 0);
   dvm_ref db = dvm_sqlite_open(vm, path, flags);
   if (!db) return false;
   RETL(db);
}

/* Context.deleteDatabase(name): the file and its journal/WAL companions. */
static bool context_delete_database(struct dvm *vm, dvm_ref self,
                                    const union dvm_value *args, int nargs,
                                    union dvm_value *out)
{
   (void)self; (void)nargs;
   const char *name = ARG(0).l ? dvm_string_utf8(vm, ARG(0).l) : NULL;
   char path[1024];
   dvm_sqlite_database_path(name, path, sizeof path);
   RETI(name && dvm_sqlite_delete_files(path));
}

static bool context_create_configuration(struct dvm *vm, dvm_ref self,
                                          const union dvm_value *args,
                                          int nargs, union dvm_value *out)
{
   if (!nargs || !ARG(0).l) {
      dvm__throw(vm, "java/lang/IllegalArgumentException",
                 "overrideConfiguration must not be null");
      return false;
   }
   union dvm_value base_resources={0},base_config={0},base_scale={0},override_scale={0};
   if(!am_vcall(vm,self,"getResources","()Landroid/content/res/Resources;",NULL,0,&base_resources) ||
      !am_vcall(vm,base_resources.l,"getConfiguration","()Landroid/content/res/Configuration;",NULL,0,&base_config)) return false;
   dvm_get_field(vm,base_config.l,"fontScale","F",&base_scale);
   dvm_get_field(vm,ARG(0).l,"fontScale","F",&override_scale);
   struct dvm_class *c = dvm__class_by_desc(vm, "Landroid/content/Context;");
   dvm_ref context = c ? dvm_new_object(vm, c) : 0;
   if (!context) return false;
   dvm_pin(vm, context);
   c = dvm__class_by_desc(vm, "Landroid/content/res/Resources;");
   dvm_ref resources = c ? dvm_new_object(vm, c) : 0;
   union dvm_value value = { .l = resources };
   bool ok = resources && dvm_set_field(vm, context, "contextResources",
                                        "Landroid/content/res/Resources;", value);
   c = dvm__class_by_desc(vm, "Landroid/content/res/Configuration;");
   dvm_ref configuration = ok && c ? dvm_new_object(vm, c) : 0;
   if (configuration) {
      value.l = configuration;
      ok = dvm_set_field(vm, resources, "configuration",
                         "Landroid/content/res/Configuration;", value);
      if (ok) ok = cfg_set_to(vm, configuration, args, 1, out);
      if(ok && !(override_scale.f>0))
         ok=dvm_set_field(vm,configuration,"fontScale","F",base_scale);
   } else ok = false;
   dvm_unpin(vm, context);
   if (!ok) return false;
   RETL(context);
}

