/* ContextThemeWrapper.setTheme(resid): the theme the context's views are
 * inflated with, kept for getThemeResId(). */
static bool context_set_theme(struct dvm *vm, dvm_ref self,
                              const union dvm_value *args, int nargs,
                              union dvm_value *out)
{
   (void)nargs;
   union dvm_value v = { .i = ARG(0).i };
   if (getenv("LUNARIA_TRACE_TA"))
      fprintf(stderr, "[theme] setTheme context=%x class=%s style=%08x\n",
              self, dvm_class_name(dvm_object_class(vm, self)), (unsigned)v.i);
   (void)dvm_set_field(vm, self, "themeResId", "I", v);
   union dvm_value theme = {0};
   (void)dvm_get_field(vm, self, "themeObject", "Landroid/content/res/Resources$Theme;", &theme);
   if (theme.l) {
      union dvm_value apply[2] = { v, { .i = 1 } };
      if (!theme_apply_style(vm, theme.l, apply, 2, out)) return false;
   }
   RETV();
}

static bool resources_new_theme(struct dvm *vm, dvm_ref self,
                                 const union dvm_value *args, int nargs,
                                 union dvm_value *out)
{
   (void)self; (void)args; (void)nargs;
   struct dvm_class *c = dvm__class_by_desc(vm, "Landroid/content/res/Resources$Theme;");
   dvm_ref theme = c ? dvm_new_object(vm, c) : 0;
   if (!theme) {
      dvm__throw(vm, "java/lang/OutOfMemoryError", "theme");
      return false;
   }
   union dvm_value resources={.l=self};
   dvm_pin(vm,theme);
   struct dvm_class *owner=self ? dvm_object_class(vm,self) : NULL;
   if(!owner || !dvm__class_assignable(vm,owner,dvm_find_class(vm,"android/content/res/Resources"))){
      if(self){if(!am_vcall(vm,self,"getResources","()Landroid/content/res/Resources;",NULL,0,&resources)){dvm_unpin(vm,theme);return false;}}
      else if(!pm_resources(vm,0,NULL,0,&resources)){dvm_unpin(vm,theme);return false;}
   }
   dvm_set_field(vm,theme,"resources","Landroid/content/res/Resources;",resources);
   dvm_unpin(vm,theme);
   RETL(theme);
}

static bool context_get_theme(struct dvm *vm, dvm_ref self,
                              const union dvm_value *args, int nargs,
                              union dvm_value *out)
{
   (void)args; (void)nargs;
   union dvm_value theme = {0}, style = {0};
   (void)dvm_get_field(vm, self, "themeObject", "Landroid/content/res/Resources$Theme;", &theme);
   if (theme.l) RETL(theme.l);
   if (!resources_new_theme(vm, self, NULL, 0, &theme)) return false;
   (void)dvm_get_field(vm, self, "themeResId", "I", &style);
   if (!style.i) {
      const char *configured = getenv("ANDROID_THEME_RESOURCE");
      if (configured) style.i = (int32_t)strtoul(configured, NULL, 0);
   }
   (void)dvm_set_field(vm, theme.l, "style", "I", style);
   (void)dvm_set_field(vm, self, "themeObject", "Landroid/content/res/Resources$Theme;", theme);
   RETL(theme.l);
}

/* Context.getSystemService() — the single name↔manager-class table.
 *
 * Android resolves a service by its string key and the caller casts the result
 * to the manager class; getSystemService(Class) and getSystemServiceName(Class)
 * are the two halves of the same mapping.  This used to be four separate
 * tables (two here, one in dvm_jni.c, one in jni_stubs.c) and they disagreed:
 * the bytecode side had never heard of "vibrator"/"vibrator_manager", so
 * GameActivity.onCreateBody() got null from
 * getSystemService(VIBRATOR_MANAGER_SERVICE) and died on the very next
 * getDefaultVibrator() — taking the whole rest of onCreate with it.  One
 * table, consulted by every path, is the fix; a service is listed here only
 * when the runtime actually defines its class. */
#define LUNARIA_DVM_MEDIA_ROUTER_IMPLEMENTATION
#include "dvm_media.h"
#undef LUNARIA_DVM_MEDIA_ROUTER_IMPLEMENTATION
static const struct dvm_system_service dvm_services[] = {
   { "accessibility", "Landroid/view/accessibility/AccessibilityManager;" },
   { "activity",      "Landroid/app/ActivityManager;" },
   { "appops",        "Landroid/app/AppOpsManager;" },
   { "audio",         "Landroid/media/AudioManager;" },
   { "autofill",      "Landroid/view/autofill/AutofillManager;" },
   { "batterymanager", "Landroid/os/BatteryManager;" },
   { "clipboard",     "Landroid/content/ClipboardManager;" },
   { "connectivity",  "Landroid/net/ConnectivityManager;" },
   { "display",       "Landroid/hardware/display/DisplayManager;" },
   { "input",         "Landroid/hardware/input/InputManager;" },
   { "input_method",  "Landroid/view/inputmethod/InputMethodManager;" },
   { "jobscheduler",  "Landroid/app/job/JobScheduler;" },
   { "layout_inflater", "Landroid/view/LayoutInflater;" },
   { "media_router", "Landroid/media/MediaRouter;" },
   { "notification",  "Landroid/app/NotificationManager;" },
   { "phone",         "Landroid/telephony/TelephonyManager;" },
   { "power",         "Landroid/os/PowerManager;" },
   { "servicediscovery", "Landroid/net/nsd/NsdManager;" },
   { "sensor",        "Landroid/hardware/SensorManager;" },
   { "uimode",        "Landroid/app/UiModeManager;" },
   { "user",          "Landroid/os/UserManager;" },
   { "vibrator",      "Landroid/os/Vibrator;" },
   { "vibrator_manager", "Landroid/os/VibratorManager;" },
   { "wifi",          "Landroid/net/wifi/WifiManager;" },
   { "window",        "Landroid/view/WindowManager;" },
};

const struct dvm_system_service *dvm_runtime_system_services(size_t *count)
{
   *count = sizeof dvm_services / sizeof dvm_services[0];
   return dvm_services;
}

/* Accepts either a service key ("vibrator"), a class descriptor
 * ("Landroid/os/Vibrator;") or a bare class name ("android/os/Vibrator"),
 * because callers reach this from getSystemService(String),
 * getSystemService(Class) and the JNI bridge alike. */
const struct dvm_system_service *dvm_runtime_find_system_service(const char *key)
{
   if (!key) return NULL;
   size_t count = 0;
   const struct dvm_system_service *table = dvm_runtime_system_services(&count);
   size_t length = strlen(key);
   for (size_t i = 0; i < count; ++i) {
      if (!strcmp(key, table[i].key)) return &table[i];
      const char *desc = table[i].desc;
      if (!strcmp(key, desc)) return &table[i];
      /* bare class name: descriptor without the leading 'L' and trailing ';' */
      size_t inner = strlen(desc) - 2;
      if (length == inner && !strncmp(key, desc + 1, inner)) return &table[i];
   }
   return NULL;
}

static dvm_ref li_new(struct dvm *vm, dvm_ref context);

dvm_ref dvm_runtime_system_service(struct dvm *vm, const char *key, dvm_ref context)
{
   const struct dvm_system_service *service = dvm_runtime_find_system_service(key);
   if (!service) return 0;
   /* Inflaters carry the context's theme and factory, so their cache belongs
    * to the context rather than to the process-wide manager table. */
   if (!strcmp(service->key, "layout_inflater")) {
      if (!context) return 0;
      union dvm_value inflater = { 0 };
      (void)dvm_get_field(vm, context, "layoutInflater", "Landroid/view/LayoutInflater;", &inflater);
      if (!inflater.l) {
         inflater.l = li_new(vm, context);
         (void)dvm_set_field(vm, context, "layoutInflater", "Landroid/view/LayoutInflater;", inflater);
      }
      return inflater.l;
   }
   /* AutofillManager is a context-scoped client even when the optional
    * system backend is absent. Do not turn absent backend into absent manager. */
   if (!strcmp(service->key, "autofill")) {
      if (!context) return 0;
      union dvm_value manager = {0};
      (void)dvm_get_field(vm, context, "autofillManager",
                         "Landroid/view/autofill/AutofillManager;", &manager);
      if (!manager.l) {
         manager.l = dvm_new_object(vm, dvm_find_class(vm, "android/view/autofill/AutofillManager"));
         if (manager.l)
            (void)dvm_set_field(vm, context, "autofillManager",
                               "Landroid/view/autofill/AutofillManager;", manager);
      }
      return manager.l;
   }
   /* One instance per service, as on a device: a manager handed out twice must
    * be the same object or state written through one reference vanishes. */
   static dvm_ref instances[sizeof dvm_services / sizeof dvm_services[0]];
   dvm_ref result=runtime_singleton(vm, service->desc,&instances[service - dvm_services]);
   if(result && !strcmp(service->key,"media_router") && !mr_ensure(vm,result,context))return 0;
   return result;
}

static bool media_router_volume_changed(struct dvm *vm)
{
   dvm_ref router=dvm_runtime_system_service(vm,"media_router",0);
   if(!router)return false;
   return mr_notify(vm,router,mr_obj(vm,router,"defaultRoute",MR_ROUTE),"onRouteVolumeChanged",0,0,0);
}

static bool context_get_system_service(struct dvm *vm, dvm_ref self,
                                       const union dvm_value *args, int nargs,
                                       union dvm_value *out)
{
   const char *key = NULL;
   struct dvm_object *arg = nargs > 0 ? dvm__obj(vm, ARG(0).l) : NULL;
   if (arg && arg->kind == DVM_OBJ_CLASS && arg->klass) {
      const struct dvm_system_service *service = dvm_runtime_find_system_service(arg->klass->name);
      if (!service) RETL(0);
      union dvm_value name = { .l = dvm_new_string(vm, service->key) };
      struct dvm_method *get = dvm_find_method(vm, dvm_object_class(vm, self),
         "getSystemService", "(Ljava/lang/String;)Ljava/lang/Object;");
      return get && dvm_call(vm, get, self, &name, 1, out);
   }
   else if (nargs > 0)
      key = dvm_string_utf8(vm, ARG(0).l);
   if (vm->trace)
      fprintf(stderr, "[dvm] Context.getSystemService(%s)\n",
              key ? key : "null");
   RETL(dvm_runtime_system_service(vm, key, self));
}

static bool context_get_system_service_name(struct dvm *vm, dvm_ref self,
                                            const union dvm_value *args,
                                            int nargs, union dvm_value *out)
{
   (void)self;
   struct dvm_object *arg = nargs ? dvm__obj(vm, ARG(0).l) : NULL;
   const char *desc = arg && arg->kind == DVM_OBJ_CLASS && arg->klass
      ? arg->klass->name : NULL;
   const struct dvm_system_service *service =
      dvm_runtime_find_system_service(desc);
   RETL(service ? dvm_new_string(vm, service->key) : 0);
}

