static bool file_output_write_impl(struct dvm *vm, dvm_ref self,
                              const union dvm_value *args, int nargs,
                              union dvm_value *out, bool bytes)
{
   union dvm_value fd = { .i = -1 };
   (void)dvm_get_field(vm, self, "fd", "I", &fd);
   if (fd.i < 0) { dvm__throw(vm, "java/io/IOException", "stream closed"); return false; }
   uint8_t one = (uint8_t)ARG(0).i;
   const void *data = &one; size_t len = 1;
   struct dvm_object *array = bytes && ARG(0).l ? dvm__obj(vm, ARG(0).l) : NULL;
   if (bytes && !array) {
      dvm__throw(vm, "java/lang/NullPointerException", "null output buffer");
      return false;
   }
   if (array && array->kind == DVM_OBJ_ARRAY) {
      int32_t offset = nargs >= 3 ? ARG(1).i : 0;
      int32_t count = nargs >= 3 ? ARG(2).i : (int32_t)array->length;
      if (!array->data || offset < 0 || count < 0 ||
          (uint32_t)offset > array->length ||
          (uint32_t)count > array->length - (uint32_t)offset) {
         dvm__throw(vm, "java/lang/IndexOutOfBoundsException", "write bounds");
         return false;
      }
      data = (const uint8_t *)array->data + offset; len = (size_t)count;
   }
   const uint8_t *p = data;
   dvm__note_io_progress(vm, len);
   /* Writing the downloaded pak is gigabytes through this loop; hold the lock
    * across it and every other thread waits on the disk.
    *
    * But giving it up is not free either.  The lock turns over once per
    * rendered frame, so a thread that hands it back after every 12 KiB of a
    * copy loop moves 12 KiB per frame — the patch download measured 0.5 MB/s
    * that way.  A short write to a regular file lands in the page cache and
    * does not wait, so it is not worth a hand-off; a big one, or a write to
    * anything that can block indefinitely (a pipe, a socket, a tty), is. */
   if (st_trace_on()) {
      static unsigned n = 0;
      if (n++ < 200u)
         fprintf(stderr, "[stream] FileOutputStream.write fd=%d len=%zu\n",
                 fd.i, len);
   }
   /* Keep the interpreter lock only for a write too small to block.
    *
    * The bound was a megabyte, on the reasoning that a short write to a
    * regular file returns immediately and three lock operations would cost
    * more than they save (UnitySampleGame writes every frame).  That holds
    * for a few hundred bytes of state; it does not hold for a bulk transfer,
    * and a bulk transfer is exactly what arrives in chunks well under a
    * megabyte: Cross Worlds downloads 228 MB through Java, and while it does,
    * "interpreter lock: held 30% of the last 5.0s, 7653.0 ms summed wait,
    * worst single wait 570.9 ms" against an execution lock at 1%, with guest
    * execution down from ~109 Mips to a few hundred instructions per five
    * seconds.  A write that reaches the page cache, let alone the disk, is not
    * something to hold a process-wide lock across. */
   int werr = 0;
   bool handoff = true;
   if (len < 4096u) {
      struct stat st;
      if (fstat(fd.i, &st) == 0 && S_ISREG(st.st_mode)) handoff = false;
   }
   unsigned gil = handoff ? dvm_gil_unlock_all(vm) : 0;
   while (len) {
      ssize_t n = luna_fd_write(fd.i, p, len);
      if (n < 0 && errno == EINTR) continue;
      if (n <= 0) { werr = errno ? errno : EIO; break; }
      p += n; len -= (size_t)n;
   }
   if (handoff) dvm_gil_relock(vm, gil);
   if (werr) {
      dvm__throw(vm, "java/io/IOException", "%s", strerror(werr));
      return false;
   }
   RETV();
}

static bool file_output_write(struct dvm *vm, dvm_ref self,
                              const union dvm_value *args, int nargs,
                              union dvm_value *out)
{
   struct dvm_method *method = dvm__builtin_method();
   bool bytes = method && method->sig && !strncmp(method->sig, "([B", 3);
   return file_output_write_impl(vm, self, args, nargs, out, bytes);
}

static bool file_output_write_array(struct dvm *vm, dvm_ref self,
                                    const union dvm_value *args, int nargs,
                                    union dvm_value *out)
{
   return file_output_write_impl(vm, self, args, nargs, out, true);
}

