/* A scalar byte lives on this host stack, so no VM storage needs to remain
 * accessible while a potentially blocking descriptor read releases the GIL. */
static ssize_t file_read_byte(struct dvm *vm, int fd, uint8_t *byte)
{
   unsigned depth = dvm_gil_unlock_all(vm);
   ssize_t n;
   do n = luna_fd_read(fd, byte, 1); while (n < 0 && errno == EINTR);
   int saved_errno = errno;
   dvm_gil_relock(vm, depth);
   errno = saved_errno;
   return n;
}

static bool file_input_read(struct dvm *vm, dvm_ref self,
                            const union dvm_value *args, int nargs,
                            union dvm_value *out)
{
   union dvm_value fd = { .i = -1 };
   (void)dvm_get_field(vm, self, "fd", "I", &fd);
   if (fd.i < 0) { dvm__throw(vm, "java/io/IOException", "stream closed"); return false; }
   if (!nargs) {
      uint8_t byte;
      ssize_t n = file_read_byte(vm, fd.i, &byte);
      if (n < 0) { dvm__throw(vm, "java/io/IOException", "%s", strerror(errno)); return false; }
      RETI(n ? byte : -1);
   }
   if (!ARG(0).l) {
      dvm__throw(vm, "java/lang/NullPointerException", "null input buffer");
      return false;
   }
   struct dvm_object *array = dvm__obj(vm, ARG(0).l);
   int32_t offset = nargs >= 3 ? ARG(1).i : 0;
   int32_t count = nargs >= 3 ? ARG(2).i : (array ? (int32_t)array->length : 0);
   if (!array || array->kind != DVM_OBJ_ARRAY || !array->data || offset < 0 ||
       count < 0 || (uint32_t)offset > array->length ||
       (uint32_t)count > array->length - (uint32_t)offset) {
      dvm__throw(vm, "java/lang/IndexOutOfBoundsException", "read bounds"); return false;
   }
   if (!count) RETI(0);
   /* Same trade as the write side: a read from a regular file is served from
    * the page cache and does not wait, so handing the lock over for it costs
    * a frame and buys nothing.  It also closes a window: `array->data` is
    * captured before the lock goes and written after it comes back, and
    * nothing may touch the VM in between.  Anything that can block without
    * end — a pipe, a socket, a tty — still gets the hand-off. */
   ssize_t n;
   {
      /* Same bound as FileOutputStream.write above, for the same reason. */
      bool handoff = true;
      if ((size_t)count < 4096u) {
         struct stat st;
         if (fstat(fd.i, &st) == 0 && S_ISREG(st.st_mode)) handoff = false;
      }
      unsigned gil = handoff ? dvm_gil_unlock_all(vm) : 0;
      do n = luna_fd_read(fd.i, (uint8_t *)array->data + offset, (size_t)count);
      while (n < 0 && errno == EINTR);
      if (handoff) dvm_gil_relock(vm, gil);
   }
   if (n < 0) { dvm__throw(vm, "java/io/IOException", "%s", strerror(errno)); return false; }
   if (n > 0) dvm__note_io_progress(vm, (size_t)n);
   RETI(n ? n : -1);
}

