static dvm_ref sock_peer_inet(struct dvm *vm, struct rt_sock *s)
{
   if (s->layered) {
      struct rt_sock *u = sock_of(vm, s->layered);
      if (u) s = u;
   }
   if (!s->connected) return 0;
   return inet_new(vm, s->host, s->addr[0] ? s->addr : s->host);
}

