   (void)dvm_set_field(vm, job, "kind", "I", (union dvm_value){ .i = r->kind });
   (void)dvm_set_field(vm, job, "terminal", "Z", (union dvm_value){ .i = terminal });
   (void)dvm_set_field(vm, job, "args", "I", (union dvm_value){ .i = argc });
